SR = 44100                    # sample rate of recordings
OUT_DIM = 64
EPOCHS = 60
EPOCHS_KFOLD = 8
LR = 0.001
N_SPLITS = 3
RANDOM_SEED = 42
KFOLD_STRATIFY_KEYS = ["device", "condition"]

# Windowing
WIN_LENGTH_SEC = 1.0
HOP_LENGTH_SEC_TRAIN = WIN_LENGTH_SEC   # no overlap: independent windows for metric learning
HOP_LENGTH_SEC_EVAL = 0.25              # with overlap: higher temporal resolution to locate the splice

# Spectral extraction (FFT)
N_FFT = 2048
HOP_LENGTH_FFT = 2048           # different from the windowing hop
STFT_WINDOW_TYPE = 'hann'       # analysis window applied to each STFT frame
LOG_POWER_EPSILON = 1e-10       # numerical floor to avoid log10(0)

# Splicing
TOP_DB = 30                    # sensitivity for detecting silence/speech

# Unvoiced-segment selection (restrict window generation to unvoiced, non-silent content)
# Unvoiced-fragment windowing (train/val only; test windows always use the full audio)
TRAIN_VAL_UNVOICED_FRAGMENTS_ENABLED = True   # master switch for fragment-based train/val windowing
# Minimum fragment duration required so that, after the two MaxPool2d(2) layers
# in Backbone (each floor-dividing the time axis by 2), at least 1 valid time
# frame survives at the pooling stage — i.e. STFT frame count T_stft >= 4, given
# T_stft = floor(n_samples / HOP_LENGTH_FFT) + 1 (librosa.stft, center=True).
# Below this, MaskedPooling's mask degenerates to all-zero and the resulting
# embedding carries no real signal even with the safety clamp in
# compute_backbone_output_time_length. Derived from HOP_LENGTH_FFT/SR instead
# of hardcoded, so it stays correct if either changes.
BACKBONE_POOL_CEIL_MODE = True
_MIN_BACKBONE_SURVIVABLE_STFT_FRAMES = 1 if BACKBONE_POOL_CEIL_MODE else 4
_MIN_STFT_CENTER_PAD_SAMPLES = N_FFT // 2 + 1   # librosa center=True reflect-pad requirement

UNVOICED_FRAGMENT_MIN_SEC = max(
    (_MIN_BACKBONE_SURVIVABLE_STFT_FRAMES - 1) * HOP_LENGTH_FFT,
    _MIN_STFT_CENTER_PAD_SAMPLES,
) / SR
UNVOICED_FRAGMENT_PAD_MODE = "reflect"        # np.pad mode for fragments shorter than WIN_LENGTH_SEC ("reflect" | "wrap")
UNVOICED_FRAGMENT_PAD_TO_WINDOW_ENABLED = False  # False = keep each fragment/chunk at its natural duration (no padding to WIN_LENGTH_SEC); True = restore the old pad-to-WIN_LENGTH_SEC behavior
UNVOICED_FMIN_HZ = librosa.note_to_hz('C2')   # lower bound of the f0 search range for voicing detection
UNVOICED_FMAX_HZ = librosa.note_to_hz('C6')   # upper bound of the f0 search range for voicing detection
UNVOICED_FRAME_LENGTH = 1024                 # pyin analysis frame length, in samples
UNVOICED_HOP_LENGTH = 128                     # pyin analysis hop length, in samples
UNVOICED_FRAGMENT_COLLATE_PAD_VALUE = 0.0

UNVOICED_ANALYSIS_SR = 16000  # pyin analysis SR; downsampled independently of SR to cut voicing-detection cost
UNVOICED_INCLUDE_SILENCE_NOISE_ENABLED = True   # True = also keep noise-only regions (below TOP_DB) that pyin flags as non-voiced; False = legacy behavior (unvoiced AND non-silent)
UNVOICED_DIGITAL_SILENCE_FILTER_ENABLED = True   # True = drop frames whose RMS is below the floor (digital zeros / near-zero padding) even when noise-only regions are included
UNVOICED_DIGITAL_SILENCE_FLOOR_DBFS = -80.0      # RMS floor in dBFS (full-scale = 0 dBFS); digital zero maps to about -200 dBFS, real mic noise floors sit well above this
TAKE_ALIGNMENT_MAX_LAG_SEC = 0.5   # search window for cross-device take-alignment diagnostic
UNVOICED_CACHE_WARMUP_N_JOBS = -1   # joblib n_jobs for unvoiced-fragment cache warm-up (-1 = all cores)
UNVOICED_SHARED_TAKE_REFERENCE_MODE = "first"   # "first" = use the first device encountered per take as the fragment-mask reference
# Concatenated unvoiced windowing: joins every unvoiced/background-noise fragment of an
# audio into one continuous signal, then cuts it into fixed-length training windows.
UNVOICED_CONCATENATION_ENABLED = True               # False = legacy per-fragment windowing
UNVOICED_CONCATENATED_KEEP_TRAILING_REMAINDER = False  # True = keep the last incomplete window if >= UNVOICED_FRAGMENT_MIN_SEC
UNVOICED_MERGE_SHORT_FRAGMENTS_ENABLED = False   # False = drop fragments shorter than UNVOICED_FRAGMENT_MIN_SEC instead of bridging the voiced gap between them
UNVOICED_VOICED_GUARD_MARGIN_SEC = 0.01          # safety margin (s) excluded around every voiced frame; absorbs pyin boundary jitter and small cross-device misalignment
UNVOICED_EXTRACTION_ALGORITHM_VERSION = 2        # bump whenever the fragment-extraction logic changes, to invalidate stale caches
UNVOICED_LISTENING_GAP_SEC = 0.05   # silence inserted between concatenated fragments, for audibility only

# Dataset per device
NUM_PER_DEVICE = None       # None = use all available
MIN_VIABLE = 3

# Train/val/test splits
TEST_SIZE = 0.3                # 70% train, 30% remainder
VAL_SIZE = 0.5                # of the remainder: 50% val / 50% test

FEATURE_DTYPE = np.float32   # dtype of the cached spectrograms
# Validation windowing mode. When True, validation windows are built from the
# full audio (same path as test), while training windows keep using unvoiced
# fragments. When False, validation mirrors the training windowing.
VALIDATION_USE_FULL_AUDIO = True
# Metric training
BATCH_SIZE = 128
TRIPLET_MARGIN = 0.2           # the one actually used (the old MARGIN=1.0 wasn't being used)
KNN_NEIGHBORS = 5
TRAIN_MINER_TYPE = "semihard"
EVAL_MINER_TYPE = "semihard"

DROPOUT_CONV = 0.1
DROPOUT_FC = 0.1
WEIGHT_DECAY = 1e-4
GRAD_CLIP_NORM = 1.0
LR_SCHEDULER_FACTOR = 0.5
LR_SCHEDULER_PATIENCE = 3
LR_SCHEDULER_THRESHOLD = 1e-4
LR_SCHEDULER_THRESHOLD_MODE = 'rel'   # 'rel' or 'abs'
LR_SCHEDULER_COOLDOWN = 0
LR_SCHEDULER_MIN_LR = 1e-6
EARLY_STOPPING_PATIENCE = 15
EARLY_STOPPING_MIN_DELTA = 1e-4
# Temporal/spatial pooling before the Neck
POOLING_TYPE = "gap"          # "gap" (baseline) | "statistical" (mean + std)
POOLING_STD_EPSILON = 1e-5            # numerical floor inside sqrt(var + eps); avoids NaN gradients when var -> 0
BACKBONE_OUT_CHANNELS = 256           # must match the last Conv2d of Backbone

# Final-model validation holdout (audio-level, stratified by KFOLD_STRATIFY_KEYS).
# Set to False to revert to training the final model on 100% of raw_train_audios.
FINAL_MODEL_USE_VALIDATION_HOLDOUT = True
FINAL_MODEL_VALIDATION_FRACTION = 0.15   # fraction of raw_train_audios (not of the full corpus)
# Training objective
TRAIN_LOSS_TYPE = "cosface"          # "triplet" | "arcface" | "cosface"

# CosFace (only used when TRAIN_LOSS_TYPE == "cosface")
COSFACE_MARGIN = 0.2                # margin in COSINE units (not degrees, unlike ArcFace)
COSFACE_SCALE = 30.0
COSFACE_LOSS_LR = LR * 10
COSFACE_LOSS_WEIGHT_DECAY = 0.0

# ArcFace (only used when TRAIN_LOSS_TYPE == "arcface")
ARCFACE_MARGIN_DEG = 28.6            # angular margin, in DEGREES (pytorch-metric-learning convention)
ARCFACE_SCALE = 64.0                 # logit scale (s)
ARCFACE_LOSS_LR = LR                 # LR for the learnable class prototypes
ARCFACE_LOSS_WEIGHT_DECAY = 0.0      # prototypes are usually not regularized

# Distance metric used for triplet mining and the triplet-margin loss.
# TRAIN_DISTANCE_P selects the Lp norm:
#   1 -> Manhattan / L1
#   2 -> Euclidean / L2
TRAIN_DISTANCE_P = 2
TRAIN_DISTANCE_NORMALIZE_EMBEDDINGS = True
# Distance/similarity metric used for triplet mining and the triplet-margin loss.
# TRAIN_DISTANCE_METRIC selects which distance object build_training_distance() returns:
#   "lp"     -> Lp norm distance (Manhattan/Euclidean, controlled by TRAIN_DISTANCE_P)
#   "cosine" -> cosine similarity (pytorch_metric_learning marks this as inverted
#               internally, so miners/losses already interpret "higher = closer" correctly)
#   "snr"    -> Signal-to-Noise Ratio distance (SNRDistance); also an inverted-similarity
#               style metric under pytorch_metric_learning's convention
TRAIN_DISTANCE_METRIC = "lp"   # "lp", "cosine", or "snr"

# EER / forensic evaluation
N_AUDIOS_TEST_EER = 200#100
N_PAIRS_ROBUSTNESS = 200
N_PAIRS_FILTERING_COMPARISON = 200   # never-seen test-set pairs sampled to compare localization strategies
N_PAIRS_PAIRWISE_CALIBRATION = 200   # window-pairs sampled for the logistic calibration back-end
THRESHOLD_DEFAULT = 0.05        # initial threshold before EER calibration
WINDOW_LEVEL_MEDIAN_FILTER_KERNEL_SIZE = 3   # must be odd; 3 = smallest meaningful window
ENTROPY_LOCAL_WINDOW = 10   # local window size (in # of consecutive-distance samples) for entropy-based localization comparison
THRESHOLD_CALIBRATION_LEVEL = "audio"   # "audio" or "window" — EER level whose optimal

# Confusion matrices
CM_NORMALIZE = "true"          # None = raw counts, "true" = row-normalized (recall), "pred" = column-normalized
CM_CLASS_NAMES_DETECTION = ["Spliced (impostor)", "Authentic (genuine)"]  # fixed labels for the binary EER problem

# Random jitter for TRAIN windows (does not apply to eval/detection windows with overlap)
JITTER_MAX_SEC = 0.1          # maximum (+/-) offset in seconds applied to the start of each train window
APPLY_JITTER_TRAIN = True     # to enable/disable jitter without touching the function
APPLY_JITTER_EVAL = False     # validation/test windows must be deterministic (no random offset)
# MPerClassSampler
_n_classes = len(device_to_label)
M_PER_CLASS = next(m for m in range(math.ceil(BATCH_SIZE / _n_classes), BATCH_SIZE + 1)
                   if BATCH_SIZE % m == 0)
# Stratified K-Fold
N_SPLITS_CV_GAP = 5

# Frequency-band ablation (tests the "device fingerprint concentrates in
# low/high bands, mid band is near-homogeneous" hypothesis on unvoiced segments)
FREQ_BAND_ABLATION_ENABLED = True        # master switch; leave False for normal training/eval runs
FREQ_BAND_LOW_CUTOFF_HZ = 100             # upper edge of the "low" band
FREQ_BAND_HIGH_CUTOFF_HZ = 3000           # lower edge of the "high" band
FREQ_BAND_MID_ATTENUATION_DB = None       # None = hard zero-out of mid band; float (e.g. 12.0) = soft attenuation instead
FREQ_BAND_ABLATION_VARIANTS = ["full_spectrum", "low_high_only", "mid_only"]
FREQ_BAND_ABLATION_CV_SPLITS = N_SPLITS_CV_GAP   # reuse existing CV-gap fold count, no new magic number

# Segment-type ablation (voiced / unvoiced / silence / unvoiced+silence / full)
SEGMENT_ABLATION_ENABLED = True
SEGMENT_ABLATION_FULL_VARIANT = "full"
SEGMENT_CATEGORY_KEYS = ["voiced", "unvoiced", "silence", "unvoiced_plus_silence"]
SEGMENT_ABLATION_VARIANTS = [SEGMENT_ABLATION_FULL_VARIANT, *SEGMENT_CATEGORY_KEYS]
SEGMENT_ABLATION_MIN_SEC = 0.1             # fragments shorter than this are dropped (no gap bridging)
SEGMENT_ABLATION_USE_STD = False           # False: per-bin mean | True: per-bin mean + std
SEGMENT_ABLATION_BALANCE_WINDOWS = True    # subsample every variant to the same window count
SEGMENT_ABLATION_CV_SPLITS = N_SPLITS_CV_GAP
SEGMENT_ABLATION_N_JOBS = UNVOICED_CACHE_WARMUP_N_JOBS
SEGMENT_ABLATION_FEATURE_EPSILON = 1e-8    # numerical floor for per-window std normalization

# Frequency-band masking applied to the ACTUAL training/evaluation pipeline
