# via k-NN and never touches the Siamese training/inference features).
TRAIN_FREQUENCY_MASKING_ENABLED = False           # master switch
TRAIN_FREQUENCY_MASK_VARIANT = "full_spectrum"   # "full_spectrum" | "low_high_only" | "mid_only"

# t-SNE
TSNE_N_ITER = 2000
TSNE_PERPLEXITY = 50
TSNE_N_COMPONENTS = 2

# Checkpointing / resume
