BOOTSTRAP_N_RESAMPLES = 1000
BOOTSTRAP_CONFIDENCE_LEVEL = 0.95
BOOTSTRAP_RANDOM_SEED = RANDOM_SEED
BOOTSTRAP_BASELINE_STRATEGY = "baseline"   # reference for paired strategy differences

# Audio-level score strategies (additional EER evaluation)
SCORE_STRATEGY_KEYS = ("baseline", "median", "median_entropy")
SCORE_STRATEGY_LABELS = {
    "baseline":       "Baseline (raw max distance)",
    "median":         "Median-filtered max distance",
    "median_entropy": "Median-filtered + entropy-weighted max score",
}
SCORE_STRATEGY_DISTANCE_METRICS = ("euclidean",)#, "mahalanobis", "manhattan", "snr")
SCORE_STRATEGY_ENTROPY_EPSILON = 1e-10   # numerical floor for the entropy-weighted ratio
SUMMARY_TABLE_DECIMALS = 4   # decimal places shown in the strategy summary table
# Cross-corpus domain-shift diagnostic
DOMAIN_SHIFT_LEVEL = "window"          # "window" or "audio" — detection level plotted
DOMAIN_SHIFT_HISTOGRAM_BINS = 20
