###########################################
"""IA-Splicing Dataset Loader"""
###########################################
def load_ia_splicing_dataset(ia_splicing_path=ia_splicing_source_path,
                              conditions=("speech_clean", "speech_noise")):
    """
    Loads pre-spliced AI-generated audio files (TTS-based splicing) along
    with their ground-truth splice metadata. Directory structure expected:
    ia_splicing_audio/<device>/<condition>/<speaker>/Splicing_IA.wav (+ metadata.json)
    """
    ia_dataset = []
    for device_folder in os.listdir(ia_splicing_path):
        device_path = os.path.join(ia_splicing_path, device_folder)
        if not os.path.isdir(device_path):
            continue
        for condition in conditions:
            condition_path = os.path.join(device_path, condition)
            if not os.path.exists(condition_path):
                continue
            for speaker_folder in os.listdir(condition_path):
                speaker_path = os.path.join(condition_path, speaker_folder)
                wav_path = os.path.join(speaker_path, "Splicing_IA.wav")
                meta_path = os.path.join(speaker_path, "metadata.json")
                if not (os.path.exists(wav_path) and os.path.exists(meta_path)):
                    print(f"WARNING: missing files in {speaker_path}")
                    continue

                with open(meta_path, "r") as f:
                    metadata = json.load(f)

                audio, sr = librosa.load(wav_path, sr=None)
                splice_info = metadata["splice"]["splice_info"]

                ia_dataset.append({
                    "audio": audio,
                    "sr": sr,
                    "filename": os.path.basename(wav_path),
                    "device": device_folder,
                    "condition": condition,
                    "speaker": speaker_folder,
                    "metadata": metadata,
                    "true_insert_start_s": splice_info["insert_start_s"],
                    "true_insert_end_s": splice_info["insert_end_s"],
                })

    print(f"Total IA-splicing audio files loaded: {len(ia_dataset)}")
    return ia_dataset

###########################################
"""Pure IA-Segment Dataset Loader (audio-level genuine pool, no splice)"""
###########################################
def load_ia_pure_set(ia_pure_set_path=ia_pure_set_source_path,
                      conditions=("speech_clean", "speech_noise")):
    """
    Loads pure, non-spliced TTS-generated audio segments used as the
    audio-level GENUINE population for the IA-splicing EER evaluation.
    Directory structure expected: audio_pure_set/<condition>/*.wav —
    flat per condition, filenames may be non-contiguous (e.g. ia_segment_1,
    ia_segment_10, ...); no metadata.json is required since there is no
    splice to localize.
    """
    pure_dataset = []
    for condition in conditions:
        condition_path = os.path.join(ia_pure_set_path, condition)
        if not os.path.exists(condition_path):
            print(f"Folder not found for condition: {condition}")
            continue
        for filename in os.listdir(condition_path):
            if not filename.endswith(".wav"):
                continue
            file_full_path = os.path.join(condition_path, filename)
            audio, sr = librosa.load(file_full_path, sr=None)
            pure_dataset.append({
                "audio": audio,
                "sr": sr,
                "filename": filename,
                "condition": condition,
            })

    print(f"Total pure IA-segment audio files loaded: {len(pure_dataset)}")
    return pure_dataset

