###########################################
"""Cross-Corpus Generalization — Unseen-Device Dataset Loader"""
###########################################

def load_unseen_devices_dataset(dataset_path=unseen_devices_repo_path, target_sr=SR):
    """
    Loads the external cross-corpus dataset (devices never present in
    device_to_label, hence never seen during training/validation/calibration).
    Audio is resampled to `target_sr` on load so the windowing and spectral
    extraction (win_sec/hop_sec expressed in samples via SR) stay consistent
    with the model's training conditions. Directory structure expected:
    <device_name>/<speaker_file>.wav — flat, single recording condition.
    """
    unseen_dataset = []
    for device_folder in sorted(os.listdir(dataset_path)):
        device_path = os.path.join(dataset_path, device_folder)
        if not os.path.isdir(device_path) or device_folder.startswith("."):
            continue
        for filename in sorted(os.listdir(device_path)):
            if not filename.endswith(".wav"):
                continue
            file_full_path = os.path.join(device_path, filename)
            audio, sr = librosa.load(file_full_path, sr=target_sr)
            unseen_dataset.append({
                "audio": audio,
                "sr": sr,
                "filename": filename,
                "device": device_folder,
                "condition": "unseen_corpus",
            })
    print(f"Total unseen-device audio files loaded: {len(unseen_dataset)}")
    return unseen_dataset


