def generate_splicing_pair(audio_info_a, audio_info_b, top_db=TOP_DB):
    audio_a_signal = audio_info_a['audio']
    audio_b_signal = audio_info_b['audio']
    sr = audio_info_a['sr']

    spliced_audio, cut_point = generate_simple_splicing(audio_a_signal, audio_b_signal, top_db=top_db)
    if spliced_audio is None:
        return None

    return {
        "audio": spliced_audio,
        "label": 0,
        "source_a": audio_info_a['device'],
        "source_b": audio_info_b['device'],
        "cut_point": cut_point,
        "cut_time": cut_point / sr
    }

