###########################################
"""Split Consistency Validation — same take must land in the same split across devices"""
###########################################

def validate_take_split_consistency(audio_dataset, raw_train_audios, val_audios, test_audios):
    """
    Verifies that every (condition, filename) take is assigned to the SAME
    split (train/val/test) across ALL devices that share it. A take split
    inconsistently across devices breaks the shared-unvoiced-fragment
    assumption (build_shared_unvoiced_fragments) and can leak train-adjacent
    content into val/test via near-identical fragment boundaries.
    """
    split_name_by_audio_id = {}
    for split_name, split_audios in (("train", raw_train_audios),
                                      ("val", val_audios),
                                      ("test", test_audios)):
        for audio_info in split_audios:
            audio_id = (audio_info["device"], audio_info["condition"], audio_info["filename"])
            split_name_by_audio_id[audio_id] = split_name

    split_names_by_take = {}
    for audio_info in audio_dataset:
        take_key = (audio_info["condition"], audio_info["filename"])
        audio_id = (audio_info["device"], audio_info["condition"], audio_info["filename"])
        split_name = split_name_by_audio_id.get(audio_id)
        split_names_by_take.setdefault(take_key, set()).add(split_name)

    inconsistent_takes = {take_key: split_names for take_key, split_names in split_names_by_take.items()
                          if len(split_names) > 1}

    print(f"Total shared takes checked: {len(split_names_by_take)}")
    if inconsistent_takes:
        print(f"WARNING: {len(inconsistent_takes)} take(s) span multiple splits:")
        for take_key, split_names in list(inconsistent_takes.items())[:20]:
            print(f"  {take_key}: {split_names}")
        if len(inconsistent_takes) > 20:
            print(f"  ... and {len(inconsistent_takes) - 20} more")
    else:
        print("All shared takes are consistently assigned to a single split.")

    return inconsistent_takes


inconsistent_takes = validate_take_split_consistency(audio_dataset, raw_train_audios, val_audios, test_audios)
if inconsistent_takes:
    raise RuntimeError(
        f"{len(inconsistent_takes)} take(s) are split inconsistently across devices — "
        f"the shared-unvoiced-fragment assumption does not hold for the current raw_split.pkl. "
        f"Regenerate the split with a filename-order-independent strategy before proceeding."
    )

# Also run with GPU
def extract_stft_power_spectrogram_db(y, sr=SR, n_fft=N_FFT, hop_length=HOP_LENGTH_FFT,
                                       window=STFT_WINDOW_TYPE, epsilon=LOG_POWER_EPSILON,
                                       freq_mask=None):
    """
    Computes the STFT power spectrogram of a waveform and converts it to
    decibels (log-power scale).

    Pipeline: STFT -> |X|^2 (power) -> optional per-bin frequency mask -> 10*log10(power + epsilon)

    Returns
    np.ndarray of shape (n_fft // 2 + 1, n_frames), dtype FEATURE_DTYPE.
    """
    stft_matrix = librosa.stft(y, n_fft=n_fft, hop_length=hop_length, window=window)
    power_spectrogram = np.abs(stft_matrix) ** 2
    if freq_mask is not None:
        power_spectrogram = power_spectrogram * freq_mask[:, None]
    power_spectrogram_db = 10 * np.log10(power_spectrogram + epsilon)
    return power_spectrogram_db.astype(FEATURE_DTYPE)

def compute_energy_sample_mask(audio, sr=SR,
                                frame_length=UNVOICED_FRAME_LENGTH, hop_length=UNVOICED_HOP_LENGTH,
                                floor_dbfs=UNVOICED_DIGITAL_SILENCE_FLOOR_DBFS,
                                epsilon=LOG_POWER_EPSILON):
    """
    Sample-level mask that is True wherever the short-time RMS level is at or
    above `floor_dbfs`. Removes digitally silent regions (exact zeros or
    near-zero padding), whose spectrograms are constant and collapse to an
    all-zero tensor after per-window normalization. Real background noise
    (well above the floor) is preserved.
    """
    rms_frames = librosa.feature.rms(y=audio, frame_length=frame_length,
                                     hop_length=hop_length, center=False)[0]
    rms_dbfs = librosa.amplitude_to_db(rms_frames, ref=1.0, amin=epsilon, top_db=None)

    energy_sample_mask = np.zeros(len(audio), dtype=bool)
    for frame_index in np.flatnonzero(rms_dbfs >= floor_dbfs):
        frame_start = frame_index * hop_length
        energy_sample_mask[frame_start:min(frame_start + frame_length, len(audio))] = True
    return energy_sample_mask

###########################################
"""Unvoiced-Segment Detection (voiced / unvoiced / silence classification)"""
###########################################

def compute_unvoiced_sample_mask(audio, sr=SR, top_db=TOP_DB,
                                  fmin=UNVOICED_FMIN_HZ, fmax=UNVOICED_FMAX_HZ,
                                  frame_length=UNVOICED_FRAME_LENGTH, hop_length=UNVOICED_HOP_LENGTH,
                                  analysis_sr=UNVOICED_ANALYSIS_SR,
                                  include_silence_noise=UNVOICED_INCLUDE_SILENCE_NOISE_ENABLED,
                                  digital_silence_filter_enabled=UNVOICED_DIGITAL_SILENCE_FILTER_ENABLED,
                                  digital_silence_floor_dbfs=UNVOICED_DIGITAL_SILENCE_FLOOR_DBFS,
                                  voiced_guard_margin_sec=UNVOICED_VOICED_GUARD_MARGIN_SEC):
    """
    Sample-level mask that is True only where NO voiced pyin frame (plus a guard
    margin) overlaps the sample. Frame centering follows librosa.pyin(center=True).
    """
    scale = analysis_sr / sr if analysis_sr < sr else 1.0
    pitch_audio = librosa.resample(audio, orig_sr=sr, target_sr=analysis_sr) if scale < 1.0 else audio
    pitch_sr = analysis_sr if scale < 1.0 else sr
    pitch_frame_length = max(int(round(frame_length * scale)), 32)
    pitch_hop_length = max(int(round(hop_length * scale)), 8)

    _, voiced_flag, _ = librosa.pyin(
        pitch_audio, fmin=fmin, fmax=fmax, sr=pitch_sr,
        frame_length=pitch_frame_length, hop_length=pitch_hop_length,
    )
    voiced_flag = np.nan_to_num(voiced_flag, nan=0.0).astype(bool)

    # pyin (center=True) centers frame i at i * pitch_hop_length; convert to original-SR samples
    frame_centers = np.round(np.arange(len(voiced_flag)) * pitch_hop_length * sr / pitch_sr).astype(np.int64)
    half_frame_span = int(round(pitch_frame_length / 2 * sr / pitch_sr))
    guard_margin_samples = int(round(voiced_guard_margin_sec * sr))
    voiced_half_span = half_frame_span + guard_margin_samples

    voiced_sample_mask = np.zeros(len(audio), dtype=bool)
    for frame_center in frame_centers[voiced_flag]:
        voiced_sample_mask[max(frame_center - voiced_half_span, 0):
                           min(frame_center + voiced_half_span, len(audio))] = True
    unvoiced_sample_mask = ~voiced_sample_mask

    if include_silence_noise:
        if digital_silence_filter_enabled:
            energy_sample_mask = compute_energy_sample_mask(
                audio, sr=sr, frame_length=frame_length, hop_length=hop_length,
                floor_dbfs=digital_silence_floor_dbfs,
            )
            return unvoiced_sample_mask & energy_sample_mask
        return unvoiced_sample_mask

    non_silent_sample_mask = np.zeros(len(audio), dtype=bool)
    for interval_start, interval_end in librosa.effects.split(audio, top_db=top_db):
        non_silent_sample_mask[interval_start:interval_end] = True
    return unvoiced_sample_mask & non_silent_sample_mask

###########################################
"""generate splicing+original windowed dataset"""
###########################################
# Also run with GPU for the kNN evaluation
def generate_splicing_windows_streaming(audio_dataset, num_per_device=NUM_PER_DEVICE, min_viable=MIN_VIABLE,
                                         win_length_sec=WIN_LENGTH_SEC, hop_length_sec=HOP_LENGTH_SEC_TRAIN, sr=SR,
                                         jitter_max_sec=JITTER_MAX_SEC, apply_jitter=APPLY_JITTER_TRAIN):
    """
    Merges prepare_complete_splicing_dataset + segment_into_windows.
    Generates each audio (spliced or genuine) and windows it on the fly,
    without keeping full raw-audio lists in memory.
    """
    win_length = int(win_length_sec * sr)
    hop_length = int(hop_length_sec * sr)
    windowed_dataset = []

    local_devices = sorted(set([a['device'] for a in audio_dataset]))
    audios_by_device = {dev: [a for a in audio_dataset if a['device'] == dev] for dev in local_devices}

    jitter_max_samples = int(jitter_max_sec * sr)

    def _window_item(audio, label, device_a, device_b, cut_point, audio_id=None):
        for nominal_start in range(0, len(audio) - win_length, hop_length):
            if apply_jitter and jitter_max_samples > 0:
                offset = random.randint(-jitter_max_samples, jitter_max_samples)
                start = min(max(nominal_start + offset, 0), len(audio) - win_length)
            else:
                start = nominal_start
            end = start + win_length

            window = audio[start:end]
            feature = extract_stft_power_spectrogram_db(window, sr, freq_mask=TRAIN_FREQUENCY_MASK)
            normalized_feature = (feature - np.mean(feature)) / (np.std(feature) + 1e-8)
            is_transition_window = cut_point is not None and start <= cut_point < end

            windowed_dataset.append({
                "spectral_feature": normalized_feature,
                "audio_id": audio_id,
                "label_spliced": label,
                "is_transition_window": is_transition_window,
                "device_a": device_a,
                "device_b": device_b,
                "timestamp_sec": start / sr,
            })

    for device_a in local_devices:
        available_audios = len(audios_by_device[device_a])
        if available_audios < min_viable:
            print(f"WARNING: {device_a} only has {available_audios} audio files (minimum: {min_viable}).")
            if available_audios == 0:
                continue

        target_count = available_audios if num_per_device is None else num_per_device
        n = min(target_count, available_audios)

        for audio_info in random.sample(audios_by_device[device_a], n):
            _window_item(
                audio_info['audio'], 1, audio_info['device'], audio_info['device'], None,
                audio_id=f"{audio_info['device']}/{audio_info['condition']}/{audio_info['filename']}"
            )

    random.shuffle(windowed_dataset)
    return windowed_dataset



