def build_shared_unvoiced_fragments(audio_dataset, sr=SR, min_fragment_sec=UNVOICED_FRAGMENT_MIN_SEC):
    """
    Computes extract_unvoiced_fragments ONCE per (condition, filename) take,
    using one representative device's audio as the reference, and reuses
    the result across every device sharing that take. Valid only when takes
    are sample-aligned across devices (validated via check_take_alignment).
    """
    fragments_by_take = {}
    for audio_info in audio_dataset:
        take_key = (audio_info['condition'], audio_info['filename'])
        if take_key in fragments_by_take:
            continue
        take_audio_id = f"take/{take_key[0]}/{take_key[1]}"
        fragments_by_take[take_key] = extract_unvoiced_fragments(
            audio_info['audio'], sr=sr, min_fragment_sec=min_fragment_sec, audio_id=take_audio_id
        )
    return fragments_by_take

def merge_short_unvoiced_fragments(candidate_fragments, min_merged_fragment_samples):
    """
    Merges consecutive unvoiced fragments — bridging the intervening
    voiced/silent gap — until each merged fragment reaches at least
    min_merged_fragment_samples, instead of discarding short fragments
    outright. Prevents windows whose STFT frame count falls below the
    minimum survivable by Backbone's two MaxPool2d(2) layers, while
    retaining audio content that would otherwise be dropped.
    """
    if not candidate_fragments:
        return candidate_fragments

    merged_fragments = []
    pending_start, pending_end = candidate_fragments[0]

    for fragment_start, fragment_end in candidate_fragments[1:]:
        if (pending_end - pending_start) >= min_merged_fragment_samples:
            merged_fragments.append((pending_start, pending_end))
            pending_start, pending_end = fragment_start, fragment_end
        else:
            pending_end = fragment_end  # bridge the gap, extend the pending span

    merged_fragments.append((pending_start, pending_end))
    return merged_fragments

def extract_unvoiced_fragments(audio, sr=SR, min_fragment_sec=UNVOICED_FRAGMENT_MIN_SEC,
                                fmin=UNVOICED_FMIN_HZ, fmax=UNVOICED_FMAX_HZ,
                                frame_length=UNVOICED_FRAME_LENGTH, hop_length=UNVOICED_HOP_LENGTH,
                                audio_id=None, cache_dir=unvoiced_fragment_cache_dir):
    cache_path = None
    if audio_id is not None:
        cache_key = hashlib.sha1(
            f"{audio_id}|{sr}|{min_fragment_sec}|{fmin}|{fmax}|{frame_length}|{hop_length}"
            f"|{UNVOICED_ANALYSIS_SR}|{UNVOICED_INCLUDE_SILENCE_NOISE_ENABLED}"
            f"|{UNVOICED_DIGITAL_SILENCE_FILTER_ENABLED}|{UNVOICED_DIGITAL_SILENCE_FLOOR_DBFS}"
            f"|{UNVOICED_VOICED_GUARD_MARGIN_SEC}|{UNVOICED_MERGE_SHORT_FRAGMENTS_ENABLED}"
            f"|{UNVOICED_EXTRACTION_ALGORITHM_VERSION}".encode()
        ).hexdigest()
        cache_path = os.path.join(cache_dir, f"{cache_key}.pkl")
        if os.path.exists(cache_path):
            with open(cache_path, "rb") as f:
                return pickle.load(f)

    unvoiced_sample_mask = compute_unvoiced_sample_mask(audio, sr=sr, fmin=fmin, fmax=fmax,
                                                        frame_length=frame_length, hop_length=hop_length)
    mask_edges = np.diff(np.concatenate([[0], unvoiced_sample_mask.astype(np.int8), [0]]))
    fragment_starts = np.flatnonzero(mask_edges == 1)
    fragment_ends = np.flatnonzero(mask_edges == -1)
    min_fragment_samples = round(min_fragment_sec * sr)

    raw_fragments = [(start, end) for start, end in zip(fragment_starts, fragment_ends)
                      if (end - start) > 0]
    if UNVOICED_MERGE_SHORT_FRAGMENTS_ENABLED:
        candidate_fragments = merge_short_unvoiced_fragments(raw_fragments, min_fragment_samples)
    else:
        candidate_fragments = raw_fragments   # never bridge across voiced gaps
    fragments = [(start, end) for start, end in candidate_fragments
                 if (end - start) >= min_fragment_samples]

    if cache_path is not None:
        with open(cache_path, "wb") as f:
            pickle.dump(fragments, f, protocol=pickle.HIGHEST_PROTOCOL)
    return fragments

def generate_concatenated_unvoiced_windows(audio_dataset, win_length_sec=WIN_LENGTH_SEC,
                                           hop_length_sec=HOP_LENGTH_SEC_TRAIN, sr=SR,
                                           min_fragment_sec=UNVOICED_FRAGMENT_MIN_SEC,
                                           keep_trailing_remainder=UNVOICED_CONCATENATED_KEEP_TRAILING_REMAINDER,
                                           shared_fragments_by_take=None):
    """
    Builds training windows from the concatenation of ALL unvoiced / background-noise
    fragments of each audio. Fragments are joined in temporal order into a single
    continuous signal, which is then segmented into windows of `win_length_sec`.
    Output schema matches generate_unvoiced_fragment_windows.

    Note: `timestamp_sec` refers to the position within the concatenated signal,
    not to the original audio timeline.
    """
    win_length = int(win_length_sec * sr)
    hop_length = int(hop_length_sec * sr)
    min_fragment_samples = round(min_fragment_sec * sr)
    windowed_dataset = []

    for audio_info in audio_dataset:
        audio = audio_info['audio']
        audio_id = f"{audio_info['device']}/{audio_info['condition']}/{audio_info['filename']}"
        if shared_fragments_by_take is not None:
            take_key = (audio_info['condition'], audio_info['filename'])
            fragments = shared_fragments_by_take.get(take_key)
        else:
            fragments = extract_unvoiced_fragments(audio, sr=sr, min_fragment_sec=min_fragment_sec, audio_id=audio_id)
        if not fragments:
            print(f"WARNING: audio_id={audio_id} has no unvoiced fragments; skipped.")
            continue

        concatenated_signal = np.concatenate([audio[start:min(end, len(audio))] for start, end in fragments])

        for window_start in range(0, len(concatenated_signal), hop_length):
            segment = concatenated_signal[window_start:window_start + win_length]
            is_incomplete_window = len(segment) < win_length
            if is_incomplete_window and not (keep_trailing_remainder and len(segment) >= min_fragment_samples):
                break

            feature = extract_stft_power_spectrogram_db(segment, sr, freq_mask=TRAIN_FREQUENCY_MASK)
            normalized_feature = (feature - np.mean(feature)) / (np.std(feature) + 1e-8)

            windowed_dataset.append({
                "spectral_feature": normalized_feature,
                "audio_id": audio_id,
                "label_spliced": 1,
                "is_transition_window": False,
                "device_a": audio_info['device'],
                "device_b": audio_info['device'],
                "timestamp_sec": window_start / sr,
            })
            if is_incomplete_window:
                break

    if len(windowed_dataset) == 0:
        raise RuntimeError("No concatenated unvoiced windows were generated. "
                           "Check compute_unvoiced_sample_mask / UNVOICED_FRAGMENT_MIN_SEC.")
    random.shuffle(windowed_dataset)
    return windowed_dataset
def generate_unvoiced_fragment_windows(audio_dataset, win_length_sec=WIN_LENGTH_SEC,
                                       hop_length_sec=HOP_LENGTH_SEC_TRAIN, sr=SR,
                                       min_fragment_sec=UNVOICED_FRAGMENT_MIN_SEC,
                                       pad_mode=UNVOICED_FRAGMENT_PAD_MODE,
                                       pad_to_window_enabled=UNVOICED_FRAGMENT_PAD_TO_WINDOW_ENABLED,
                                       shared_fragments_by_take=None):
    """
    Builds windows exclusively from unvoiced fragments, one fragment at a time
    (no concatenation across fragments). Fragments shorter than the window are
    padded to `win_length_sec`; longer ones are split into consecutive windows.
    Output schema matches generate_splicing_windows_streaming.
    """
    win_length = int(win_length_sec * sr)
    hop_length = int(hop_length_sec * sr)
    min_fragment_samples = round(min_fragment_sec * sr)
    windowed_dataset = []

    for audio_info in audio_dataset:
        audio = audio_info['audio']
        audio_id = f"{audio_info['device']}/{audio_info['condition']}/{audio_info['filename']}"
        if shared_fragments_by_take is not None:
            take_key = (audio_info['condition'], audio_info['filename'])
            fragments = shared_fragments_by_take.get(take_key)
        else:
            fragments = extract_unvoiced_fragments(audio, sr=sr, min_fragment_sec=min_fragment_sec, audio_id=audio_id)
        if not fragments:
            print(f"WARNING: audio_id={audio_id} has no unvoiced fragments; skipped.")
            continue

        for fragment_start, fragment_end in fragments:
            for window_start in range(fragment_start, fragment_end, hop_length):
                segment = audio[window_start:min(window_start + win_length, fragment_end)]
                is_trailing_chunk = window_start > fragment_start
                if is_trailing_chunk and len(segment) < min_fragment_samples:
                    continue
                if pad_to_window_enabled and len(segment) < win_length:
                    segment = np.pad(segment, (0, win_length - len(segment)), mode=pad_mode)

                feature = extract_stft_power_spectrogram_db(segment, sr, freq_mask=TRAIN_FREQUENCY_MASK)
                normalized_feature = (feature - np.mean(feature)) / (np.std(feature) + 1e-8)

                windowed_dataset.append({
                    "spectral_feature": normalized_feature,
                    "audio_id": audio_id,
                    "label_spliced": 1,
                    "is_transition_window": False,
                    "device_a": audio_info['device'],
                    "device_b": audio_info['device'],
                    "timestamp_sec": window_start / sr,
                })

    if len(windowed_dataset) == 0:
        raise RuntimeError("No unvoiced-fragment windows were generated. "
                           "Check compute_unvoiced_sample_mask / UNVOICED_FRAGMENT_MIN_SEC.")
    random.shuffle(windowed_dataset)
    return windowed_dataset


def generate_train_val_windows(audio_items, apply_jitter, is_validation=False):
    """Dispatches windowing between unvoiced fragments (per-fragment or concatenated) and the full-audio path."""
    use_unvoiced_fragments = (
        TRAIN_VAL_UNVOICED_FRAGMENTS_ENABLED
        and not (is_validation and VALIDATION_USE_FULL_AUDIO)
    )
    if use_unvoiced_fragments:
        unvoiced_window_builder = (generate_concatenated_unvoiced_windows
                                   if UNVOICED_CONCATENATION_ENABLED
                                   else generate_unvoiced_fragment_windows)
        return unvoiced_window_builder(audio_items, shared_fragments_by_take=shared_unvoiced_fragments)
    return generate_splicing_windows_streaming(
        audio_items, num_per_device=None, sr=SR, apply_jitter=apply_jitter
    )

