def visualize_splicing(original_audio, spliced_audio, sr=SR, n_fft=N_FFT, hop_length=HOP_LENGTH_FFT):
    plt.figure(figsize=(12, 8))

    # FFT (Log-Power) spectrogram of the Original
    plt.subplot(2, 1, 1)
    orig_stft = librosa.stft(original_audio, n_fft=n_fft, hop_length=hop_length, window='hann')
    orig_db = 10 * np.log10(np.abs(orig_stft)**2 + 1e-10)
    librosa.display.specshow(orig_db, sr=sr, hop_length=hop_length,
                              x_axis='time', y_axis='linear')
    plt.title('Original Audio (Single Device) — FFT Log-Power')
    plt.colorbar(format='%+2.0f dB')

    # FFT (Log-Power) spectrogram of the Spliced (Corrupted) audio
    plt.subplot(2, 1, 2)
    splice_stft = librosa.stft(spliced_audio, n_fft=n_fft, hop_length=hop_length, window='hann')
    splice_db = 10 * np.log10(np.abs(splice_stft)**2 + 1e-10)
    librosa.display.specshow(splice_db, sr=sr, hop_length=hop_length,
                              x_axis='time', y_axis='linear')
    plt.title('Spliced Audio (Device Change) — FFT Log-Power')
    plt.colorbar(format='%+2.0f dB')

    plt.tight_layout()
    plt.show()


