###########################################
"""Listen to Extracted Unvoiced Fragments — Auditory Verification"""
###########################################

def listen_to_unvoiced_fragments(audio_info, sr=SR, min_fragment_sec=UNVOICED_FRAGMENT_MIN_SEC,
                                  gap_sec=UNVOICED_LISTENING_GAP_SEC, save_wav=True,
                                  output_dir=unvoiced_listening_samples_dir):
    """
    Extracts the unvoiced fragments of a single audio using the pipeline's
    existing extract_unvoiced_fragments(), concatenates them with a short
    silence gap for audibility, and renders both the original and the
    unvoiced-only reconstruction for inline playback.

    Parameters
    ----------
    audio_info : dict
        An element of audio_dataset (must contain 'audio', 'sr', 'device',
        'condition', 'filename').
    gap_sec : float
        Silence inserted between consecutive fragments, purely for
        listening purposes — does not affect the training/eval pipeline.
    save_wav : bool
        If True, saves the unvoiced-only reconstruction to output_dir.

    Returns
    -------
    dict with: concatenated_audio, fragments, fragment_durations_sec,
    total_original_duration_sec, total_unvoiced_duration_sec, wav_path
    (wav_path is None when save_wav=False).
    """
    audio = audio_info['audio']
    audio_id = f"{audio_info['device']}/{audio_info['condition']}/{audio_info['filename']}"

    fragments = extract_unvoiced_fragments(audio, sr=sr, min_fragment_sec=min_fragment_sec, audio_id=audio_id)

    if not fragments:
        print(f"WARNING: no unvoiced fragments found for {audio_id}")
        return None

    gap_samples = int(gap_sec * sr)
    gap_silence = np.zeros(gap_samples, dtype=audio.dtype)

    pieces = []
    for fragment_start, fragment_end in fragments:
        pieces.append(audio[fragment_start:fragment_end])
        pieces.append(gap_silence)

    concatenated_audio = np.concatenate(pieces)
    fragment_durations_sec = [(fragment_end - fragment_start) / sr for fragment_start, fragment_end in fragments]
    total_unvoiced_duration_sec = float(np.sum(fragment_durations_sec))
    total_original_duration_sec = len(audio) / sr

    print(f"\n--- {audio_id} ---")
    print(f"Original duration: {total_original_duration_sec:.4f}s")
    print(f"Fragments extracted: {len(fragments)}")
    print(f"Total unvoiced duration: {total_unvoiced_duration_sec:.4f}s "
          f"({100 * total_unvoiced_duration_sec / total_original_duration_sec:.4f}% of original)")
    print(f"Mean fragment duration: {np.mean(fragment_durations_sec):.4f}s "
          f"± {np.std(fragment_durations_sec):.4f}s")

    print("\n>>> ORIGINAL audio (reference):")
    display(Audio(audio, rate=sr))

    print(">>> UNVOICED-ONLY fragments (concatenated):")
    display(Audio(concatenated_audio, rate=sr))

    wav_path = None
    if save_wav:
        wav_filename = f"unvoiced_only_{audio_info['device']}_{audio_info['condition']}_{audio_info['filename']}"
        wav_path = os.path.join(output_dir, wav_filename)
        sf.write(wav_path, concatenated_audio, sr)
        print(f"Saved to: {wav_path}")

    return {
        "concatenated_audio": concatenated_audio,
        "fragments": fragments,
        "fragment_durations_sec": fragment_durations_sec,
        "total_original_duration_sec": total_original_duration_sec,
        "total_unvoiced_duration_sec": total_unvoiced_duration_sec,
        "wav_path": wav_path,
    }

sample_device = random.choice(devices)

