def cache_stratified_folds(raw_train_audios, n_splits=N_SPLITS, seed=RANDOM_SEED,
                            stratify_keys=KFOLD_STRATIFY_KEYS, output_dir=output_path):
    """
    Splits raw_train_audios into stratified folds and caches each fold's
    train/val windows to disk. Stratification ensures every fold contains
    a balanced number of audios per device (and, by default, per recording
    condition).
    """
    stratification_labels = build_stratification_labels(raw_train_audios, stratify_keys)
    kfold_splitter = StratifiedKFold(n_splits=n_splits, shuffle=True, random_state=seed)
    indices = np.arange(len(raw_train_audios))

    for fold_index, (train_idx, val_idx) in enumerate(kfold_splitter.split(indices, stratification_labels)):
        fold_path = os.path.join(output_dir, f"fold_{fold_index + 1}.pkl")

        # If it already exists, skip (resume where it left off)
        if os.path.exists(fold_path):
            print(f"Fold {fold_index + 1} already exists at {fold_path}, skipping.")
            continue

        random.seed(seed + fold_index)  # reproducible per fold

        fold_train_audios = [raw_train_audios[i] for i in train_idx]
        fold_val_audios = [raw_train_audios[i] for i in val_idx]

        validate_fold_composition(fold_index, fold_train_audios, fold_val_audios,   #BORRAR DESPUES DE REVISAR Q SI ESTE BIEN JUNTO CON LO DE ARRIBA
                                   stratify_keys=stratify_keys, min_count=MIN_VIABLE)

        train_windows = generate_train_val_windows(fold_train_audios, apply_jitter=APPLY_JITTER_TRAIN)
        val_windows = generate_train_val_windows(
            fold_val_audios, apply_jitter=APPLY_JITTER_EVAL, is_validation=True
        )

        with open(fold_path, "wb") as f:
            pickle.dump({"train": train_windows, "val": val_windows}, f,
                        protocol=pickle.HIGHEST_PROTOCOL)
        print(f"Fold {fold_index + 1} cached at {fold_path}")

        del train_windows, val_windows, fold_train_audios, fold_val_audios
        gc.collect()


cache_stratified_folds(raw_train_audios, n_splits=N_SPLITS)

