###########################################
"""Segment-Type Ablation — Voiced / Unvoiced / Silence / Unvoiced+Silence / Full"""
###########################################
# Segment partition (per audio, within energy-valid samples):
#   silence               = ~non_silent(TOP_DB)
#   unvoiced              =  unvoiced(pyin) & non_silent
#   voiced                = ~unvoiced(pyin) & non_silent
#   unvoiced_plus_silence = unvoiced | silence
#   full                  = fixed-length windows over the entire audio

def _mask_to_intervals(mask):
    """Converts a boolean sample mask into a list of (start, end) sample intervals."""
    edges = np.diff(np.concatenate([[0], mask.astype(np.int8), [0]]))
    return [(int(start), int(end))
            for start, end in zip(np.flatnonzero(edges == 1), np.flatnonzero(edges == -1))]


def compute_segment_category_intervals(audio, sr=SR, top_db=TOP_DB):
    """
    Partitions one audio into voiced / unvoiced / silence / unvoiced+silence
    sample intervals. Voicing detection is delegated to compute_unvoiced_sample_mask()
    so the categories stay consistent with the training pipeline.
    """
    unvoiced_energy_mask = compute_unvoiced_sample_mask(
        audio, sr=sr, top_db=top_db,
        include_silence_noise=True, digital_silence_filter_enabled=True,
    )
    energy_mask = compute_energy_sample_mask(audio, sr=sr)

    non_silent_mask = np.zeros(len(audio), dtype=bool)
    for interval_start, interval_end in librosa.effects.split(audio, top_db=top_db):
        non_silent_mask[interval_start:interval_end] = True

    unvoiced_mask = unvoiced_energy_mask & non_silent_mask
    voiced_mask = energy_mask & non_silent_mask & ~unvoiced_energy_mask
    silence_mask = energy_mask & ~non_silent_mask

    # Order must match SEGMENT_CATEGORY_KEYS
    category_masks = (voiced_mask, unvoiced_mask, silence_mask, unvoiced_mask | silence_mask)
    return {key: _mask_to_intervals(mask) for key, mask in zip(SEGMENT_CATEGORY_KEYS, category_masks)}


def build_segment_category_intervals_by_take(audio_pool, sr=SR, n_jobs=SEGMENT_ABLATION_N_JOBS,
                                              cache_dir=segment_category_cache_dir):
    """
    Runs the (expensive) voicing detection once per (condition, filename) take and
    reuses it across devices, valid because takes are sample-aligned across devices.
    Results are cached to disk.
    """
    reference_audio_by_take = {}
    for audio_info in audio_pool:
        reference_audio_by_take.setdefault((audio_info['condition'], audio_info['filename']), audio_info)
    take_keys = sorted(reference_audio_by_take)

    cache_signature = hashlib.sha1(
        f"{take_keys}|{sr}|{TOP_DB}|{UNVOICED_ANALYSIS_SR}|{UNVOICED_FRAME_LENGTH}|{UNVOICED_HOP_LENGTH}"
        f"|{UNVOICED_FMIN_HZ}|{UNVOICED_FMAX_HZ}|{UNVOICED_DIGITAL_SILENCE_FLOOR_DBFS}"
        f"|{UNVOICED_VOICED_GUARD_MARGIN_SEC}|{UNVOICED_EXTRACTION_ALGORITHM_VERSION}".encode()
    ).hexdigest()
    cache_path = os.path.join(cache_dir, f"segment_category_intervals_{cache_signature}.pkl")
    if os.path.exists(cache_path):
        print(f"Segment-category intervals cache found: {cache_path}")
        with open(cache_path, "rb") as f:
            return pickle.load(f)

    print(f"Computing segment categories for {len(take_keys)} takes...")
    intervals_per_take = Parallel(n_jobs=n_jobs)(
        delayed(compute_segment_category_intervals)(reference_audio_by_take[take_key]['audio'], sr)
        for take_key in take_keys
    )
    intervals_by_take = dict(zip(take_keys, intervals_per_take))
    with open(cache_path, "wb") as f:
        pickle.dump(intervals_by_take, f, protocol=pickle.HIGHEST_PROTOCOL)
    return intervals_by_take


def _iter_full_windows(audio, sr, win_length_sec, hop_length_sec):
    win_length, hop_length = int(win_length_sec * sr), int(hop_length_sec * sr)
    for start in range(0, len(audio) - win_length, hop_length):
        yield audio[start:start + win_length]


def _iter_category_segments(audio, intervals, sr, win_length_sec, min_segment_sec):
    """One fragment at a time (no concatenation); long fragments are split into chunks <= win_length_sec."""
    win_length, min_samples = int(win_length_sec * sr), round(min_segment_sec * sr)
    for interval_start, interval_end in intervals:
        interval_end = min(interval_end, len(audio))
        for window_start in range(interval_start, interval_end, win_length):
            segment = audio[window_start:min(window_start + win_length, interval_end)]
            if len(segment) >= min_samples:
                yield segment


def _pooled_spectral_descriptor(segment, sr, n_fft, hop_length_fft, use_std,
                                epsilon=SEGMENT_ABLATION_FEATURE_EPSILON):
    """
    Collapses the time axis into a fixed-length vector so variable-duration segments
    are comparable. Same per-window normalization as the rest of the pipeline.
    """
    feature = extract_stft_power_spectrogram_db(segment, sr=sr, n_fft=n_fft, hop_length=hop_length_fft)
    normalized_feature = (feature - np.mean(feature)) / (np.std(feature) + epsilon)
    descriptor = normalized_feature.mean(axis=1)
    if use_std:
        descriptor = np.concatenate([descriptor, normalized_feature.std(axis=1)])
    return descriptor


def run_segment_type_ablation(audio_pool, device_to_label, variants=SEGMENT_ABLATION_VARIANTS,
                               sr=SR, n_fft=N_FFT, hop_length_fft=HOP_LENGTH_FFT,
                               win_length_sec=WIN_LENGTH_SEC, hop_length_sec=HOP_LENGTH_SEC_TRAIN,
                               min_segment_sec=SEGMENT_ABLATION_MIN_SEC, use_std=SEGMENT_ABLATION_USE_STD,
                               balance_windows=SEGMENT_ABLATION_BALANCE_WINDOWS,
                               knn_neighbors=KNN_NEIGHBORS, cv_splits=SEGMENT_ABLATION_CV_SPLITS,
                               random_seed=RANDOM_SEED, stratify_keys=KFOLD_STRATIFY_KEYS):
    """
    For each segment type, measures device separability (k-NN, audio-grouped stratified CV)
    on pooled log-power descriptors. No Siamese embedding involved.
    """
    intervals_by_take = None
    if any(variant != SEGMENT_ABLATION_FULL_VARIANT for variant in variants):
        intervals_by_take = build_segment_category_intervals_by_take(audio_pool, sr=sr)

    audio_stratification_labels = build_stratification_labels(audio_pool, stratify_keys)
    collected_by_variant = {}

    for variant in variants:
        features, labels, group_ids, stratification_labels, total_samples = [], [], [], [], 0
        for audio_index, audio_info in enumerate(audio_pool):
            audio_signal = audio_info['audio']
            if variant == SEGMENT_ABLATION_FULL_VARIANT:
                segments = _iter_full_windows(audio_signal, sr, win_length_sec, hop_length_sec)
            else:
                take_key = (audio_info['condition'], audio_info['filename'])
                segments = _iter_category_segments(
                    audio_signal, intervals_by_take[take_key][variant], sr, win_length_sec, min_segment_sec
                )
            for segment in segments:
                features.append(_pooled_spectral_descriptor(segment, sr, n_fft, hop_length_fft, use_std))
                labels.append(device_to_label[audio_info['device']])
                group_ids.append(audio_index)
                stratification_labels.append(audio_stratification_labels[audio_index])
                total_samples += len(segment)

        if not features:
            print(f"[{variant}] no segments found, skipped.")
            continue
        collected_by_variant[variant] = {
            "features": np.stack(features, axis=0),
            "labels": np.asarray(labels),
            "groups": np.asarray(group_ids),
            "stratification": np.asarray(stratification_labels),
            "n_windows_before_balancing": len(labels),
            "total_duration_sec": total_samples / sr,
        }
        print(f"[{variant}] windows={len(labels)} | duration={total_samples / sr / 60:.1f} min")

    if balance_windows and collected_by_variant:
        min_window_count = min(len(v["labels"]) for v in collected_by_variant.values())
        rng = np.random.default_rng(random_seed)
        print(f"Balancing all variants to {min_window_count} windows each.")
        for v in collected_by_variant.values():
            if len(v["labels"]) > min_window_count:
                keep_indices = np.sort(rng.choice(len(v["labels"]), size=min_window_count, replace=False))
                for key in ("features", "labels", "groups", "stratification"):
                    v[key] = v[key][keep_indices]

    results = {}
    for variant, v in collected_by_variant.items():
        knn_model = KNeighborsClassifier(n_neighbors=knn_neighbors, metric="euclidean")
        cv_splitter = StratifiedGroupKFold(n_splits=cv_splits, shuffle=True, random_state=random_seed)
        audio_level_splits = list(cv_splitter.split(v["features"], v["stratification"], groups=v["groups"]))
        cv_accuracy = cross_val_score(knn_model, v["features"], v["labels"], cv=audio_level_splits, scoring='accuracy')

        results[variant] = {
            "mean_accuracy": float(cv_accuracy.mean()),
            "std_accuracy": float(cv_accuracy.std()),
            "n_windows": int(len(v["labels"])),
            "n_windows_before_balancing": int(v["n_windows_before_balancing"]),
            "n_audios_with_data": int(len(np.unique(v["groups"]))),
            "total_duration_sec_before_balancing": float(v["total_duration_sec"]),
        }
        print(f"[{variant}] k-NN device-CV accuracy: {cv_accuracy.mean():.4%} ± {cv_accuracy.std():.4%} "
              f"(n={len(v['labels'])})")

    del collected_by_variant
    gc.collect()
    return results


def plot_segment_type_ablation(results, output_path=segment_ablation_png_path, dpi=FIGURE_DPI):
    variant_names = list(results.keys())
    mean_accuracies = [results[v]["mean_accuracy"] for v in variant_names]
    std_accuracies = [results[v]["std_accuracy"] for v in variant_names]

    fig, ax = plt.subplots(figsize=(10, 6))
    bars = ax.bar(variant_names, mean_accuracies, yerr=std_accuracies, color='steelblue', alpha=0.85, capsize=8)
    for bar, value in zip(bars, mean_accuracies):
        ax.text(bar.get_x() + bar.get_width() / 2, value + 0.02, f'{value:.4%}',
                ha='center', fontweight='bold', fontsize=9)
    ax.set_ylabel('k-NN Device-Classification Accuracy (CV)')
    ax.set_ylim(0, 1.05)
    ax.set_xticks(range(len(variant_names)))
    ax.set_xticklabels(variant_names, rotation=15, ha='right')
    ax.set_title('Segment-Type Ablation — Device Discriminability', fontweight='bold')
    ax.grid(True, axis='y', alpha=0.3)
    plt.tight_layout()

    plt.savefig(output_path, dpi=dpi, bbox_inches='tight')
    plt.show()
    print(f"Segment-type ablation plot saved to {output_path}")


