def build_training_distance(metric: str = TRAIN_DISTANCE_METRIC,
                             p: int = TRAIN_DISTANCE_P,
                             normalize_embeddings: bool = TRAIN_DISTANCE_NORMALIZE_EMBEDDINGS):
    """Factory for the miner/loss distance object, so the metric used
    for training can be swapped (L1, L2, cosine, SNR, etc.) from a single config
    variable without touching train_with_kfold / train_final_model."""
    if metric == "cosine":
        return CosineSimilarity()
    elif metric == "lp":
        return LpDistance(p=p, normalize_embeddings=normalize_embeddings)
    elif metric == "snr":
        return SNRDistance(normalize_embeddings=normalize_embeddings)
    else:
        raise ValueError(f"Unsupported TRAIN_DISTANCE_METRIC: {metric}")

def build_metric_learning_components(model, lr=LR, loss_type=TRAIN_LOSS_TYPE,
                                     num_classes=len(device_to_label), out_dim=OUT_DIM,
                                     device=device):
    """
    Builds the optimizer, loss function and pytorch-metric-learning adapter
    for the selected training objective.

    - "triplet": TripletMarginLoss + TripletMarginMiner (parameter-free loss).
    - "arcface": ArcFaceLoss. Owns learnable class prototypes
                 W in R^{num_classes x out_dim}, so its parameters MUST be
                 optimized jointly with the backbone. No miner is required
                 (classification-based loss).
    - "cosface": CosFaceLoss. Same prototype-based scheme as ArcFace, with an
                 additive margin applied in cosine space.

    Returns
    -------
    optimizer, loss_fn, adapter
    """
    if loss_type == "triplet":
        train_miner = miners.TripletMarginMiner(margin=TRIPLET_MARGIN, type_of_triplets=TRAIN_MINER_TYPE,
                                                distance=build_training_distance())
        eval_miner = miners.TripletMarginMiner(margin=TRIPLET_MARGIN, type_of_triplets=EVAL_MINER_TYPE,
                                               distance=build_training_distance())
        loss_fn = losses.TripletMarginLoss(margin=TRIPLET_MARGIN, distance=build_training_distance())
        optimizer = torch.optim.AdamW(model.parameters(), lr=lr, weight_decay=WEIGHT_DECAY)

        def adapter(model, batch, func):
            if len(batch) == 3:
                specs, labels, valid_time_lengths = batch
                valid_time_lengths = valid_time_lengths.to(specs.device)
            else:
                specs, labels = batch
                valid_time_lengths = None
            embeddings = model(specs, valid_time_lengths)
            active_miner = train_miner if model.training else eval_miner
            return func(embeddings, labels, active_miner(embeddings, labels))

    elif loss_type == "arcface":
        loss_fn = losses.ArcFaceLoss(num_classes=num_classes, embedding_size=out_dim,
                                     margin=ARCFACE_MARGIN_DEG, scale=ARCFACE_SCALE).to(device)
        optimizer = torch.optim.AdamW([
            {"params": model.parameters(),   "lr": lr,              "weight_decay": WEIGHT_DECAY},
            {"params": loss_fn.parameters(), "lr": ARCFACE_LOSS_LR, "weight_decay": ARCFACE_LOSS_WEIGHT_DECAY},
        ])

        def adapter(model, batch, func):
            if len(batch) == 3:
                specs, labels, valid_time_lengths = batch
                valid_time_lengths = valid_time_lengths.to(specs.device)
            else:
                specs, labels = batch
                valid_time_lengths = None
            embeddings = model(specs, valid_time_lengths)
            return func(embeddings, labels)

    elif loss_type == "cosface":
        loss_fn = losses.CosFaceLoss(num_classes=num_classes, embedding_size=out_dim,
                                     margin=COSFACE_MARGIN, scale=COSFACE_SCALE).to(device)
        optimizer = torch.optim.AdamW([
            {"params": model.parameters(),   "lr": lr,              "weight_decay": WEIGHT_DECAY},
            {"params": loss_fn.parameters(), "lr": COSFACE_LOSS_LR, "weight_decay": COSFACE_LOSS_WEIGHT_DECAY},
        ])

        def adapter(model, batch, func):
            if len(batch) == 3:
                specs, labels, valid_time_lengths = batch
                valid_time_lengths = valid_time_lengths.to(specs.device)
            else:
                specs, labels = batch
                valid_time_lengths = None
            embeddings = model(specs, valid_time_lengths)
            return func(embeddings, labels)

    else:
        raise ValueError(f"Unsupported TRAIN_LOSS_TYPE: {loss_type}")

    return optimizer, loss_fn, adapter


def get_active_loss_config(loss_type: str = TRAIN_LOSS_TYPE) -> dict:
    """
    Returns only the hyperparameters relevant to the active training objective,
    so saved experiment configs never mix (or omit) loss-specific settings.
    """
    if loss_type == "triplet":
        return {
            "TRAIN_LOSS_TYPE": loss_type,
            "TRIPLET_MARGIN": TRIPLET_MARGIN,
            "TRAIN_MINER_TYPE": TRAIN_MINER_TYPE,
            "EVAL_MINER_TYPE": EVAL_MINER_TYPE,
            "TRAIN_DISTANCE_METRIC": TRAIN_DISTANCE_METRIC,
            "TRAIN_DISTANCE_P": TRAIN_DISTANCE_P,
        }
    if loss_type == "arcface":
        return {
            "TRAIN_LOSS_TYPE": loss_type,
            "ARCFACE_MARGIN_DEG": ARCFACE_MARGIN_DEG,
            "ARCFACE_SCALE": ARCFACE_SCALE,
        }
    if loss_type == "cosface":
        return {
            "TRAIN_LOSS_TYPE": loss_type,
            "COSFACE_MARGIN": COSFACE_MARGIN,
            "COSFACE_SCALE": COSFACE_SCALE,
        }
    raise ValueError(f"Unsupported TRAIN_LOSS_TYPE: {loss_type}")

