# Auxiliary loader only for extracting embeddings with device label

class EmbeddingExtractionDataset(Dataset):
    def __init__(self, window_list, device_to_label, global_mean=None, global_std=None):
        self.data = window_list
        self.device_to_label = device_to_label
        #self.global_mean = global_mean
        #self.global_std = global_std

    def __len__(self):
        return len(self.data)

    def __getitem__(self, idx):
        item = self.data[idx]
        spec = torch.tensor(item['spectral_feature'], dtype=torch.float32).unsqueeze(0)

        #if self.global_mean is not None and self.global_std is not None:
        #    spec = (spec - self.global_mean) / (self.global_std + 1e-8)

        label = self.device_to_label[item['device_b']]
        return spec, torch.tensor(label, dtype=torch.long)

def collate_variable_length_spectrograms(batch, pad_value=UNVOICED_FRAGMENT_COLLATE_PAD_VALUE):
    """
    Required collate_fn when TRAIN_VAL_UNVOICED_FRAGMENTS_ENABLED=True and
    UNVOICED_FRAGMENT_PAD_TO_WINDOW_ENABLED=False: unvoiced-fragment windows keep
    their natural duration, so time-frame count varies per sample. Pads every
    spectrogram to the batch's max time-frame count for stacking, and returns the
    pre-padding valid length per sample so EmbeddingNet.forward can mask the padding
    out at pooling time instead of treating it as real signal.
    """
    specs, labels = zip(*batch)
    valid_time_lengths = torch.tensor([spec.shape[-1] for spec in specs], dtype=torch.long)
    max_time_frames = int(valid_time_lengths.max().item())
    padded_specs = [
        F.pad(spec, (0, max_time_frames - spec.shape[-1]), mode="constant", value=pad_value)
        for spec in specs
    ]
    return torch.stack(padded_specs, dim=0), torch.stack(labels, dim=0), valid_time_lengths

def extract_embeddings(model, loader, device):
    model.eval()
    embeddings = []
    labels = []
    with torch.no_grad():
        for batch in loader:
            if len(batch) == 3:
                specs, target_labels, valid_time_lengths = batch
                valid_time_lengths = valid_time_lengths.to(device)
            else:
                specs, target_labels = batch
                valid_time_lengths = None

            specs = specs.to(device)
            output = model(specs, valid_time_lengths)

            embeddings.append(output.cpu())
            labels.append(target_labels)

    return torch.cat(embeddings), torch.cat(labels)

