class EfficientChannelAttention(nn.Module):
    """
    ECA-Net channel attention (Wang et al., 2020). Applies a lightweight
    1D convolution over channel-wise global average pooled features to
    model local cross-channel interaction, avoiding the dimensionality
    reduction used in Squeeze-and-Excitation blocks.
    """
    def __init__(self, num_channels: int, gamma: int = 2, beta: int = 1):
        super().__init__()
        kernel_size = int(abs((torch.log2(torch.tensor(float(num_channels))) + beta) / gamma))
        kernel_size = kernel_size if kernel_size % 2 else kernel_size + 1
        kernel_size = max(kernel_size, 3)

        self.global_pool = nn.AdaptiveAvgPool2d(1)
        self.channel_conv = nn.Conv1d(
            in_channels=1, out_channels=1, kernel_size=kernel_size,
            padding=(kernel_size - 1) // 2, bias=False
        )
        self.gate = nn.Sigmoid()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        channel_descriptor = self.global_pool(x)                       # [B, C, 1, 1]
        channel_descriptor = channel_descriptor.squeeze(-1).transpose(-1, -2)  # [B, 1, C]
        channel_attention = self.channel_conv(channel_descriptor)      # [B, 1, C]
        channel_attention = channel_attention.transpose(-1, -2).unsqueeze(-1)  # [B, C, 1, 1]
        return x * self.gate(channel_attention)

###########################################
"""EmbeddingNet Backbone+Neck+EmbeddingNet"""
###########################################
class Backbone(nn.Sequential):
    def __init__(self, dropout_conv=0.1):
        super().__init__(
            # Input: [1, F, T]  (F=freq bins, T=temporal frames)
            nn.Conv2d(1, 64, kernel_size=3, padding=1),
            nn.BatchNorm2d(64),
            nn.ReLU(),
            nn.MaxPool2d(2, ceil_mode=BACKBONE_POOL_CEIL_MODE),
            nn.Dropout2d(dropout_conv),

            nn.Conv2d(64, 128, kernel_size=3, padding=1),
            nn.BatchNorm2d(128),
            nn.ReLU(),
            nn.MaxPool2d(2, ceil_mode=BACKBONE_POOL_CEIL_MODE),
            nn.Dropout2d(dropout_conv),

            nn.Conv2d(128, BACKBONE_OUT_CHANNELS, kernel_size=3, padding=1),
            nn.BatchNorm2d(BACKBONE_OUT_CHANNELS),
            nn.ReLU(),
            #EfficientChannelAttention(num_channels=256),  # ECA block
            #nn.MaxPool2d(2),
            nn.Dropout2d(dropout_conv),
        )
class StatisticsPooling(nn.Module):
    """
    Statistical pooling (x-vector / ECAPA-TDNN style). Concatenates the mean and
    standard deviation of each channel computed over all spatial positions
    (frequency x time), so the descriptor captures variability, not only the average.

    Input : [B, C, H, W]
    Output: [B, 2 * C]
    """
    def __init__(self, epsilon: float = POOLING_STD_EPSILON):
        super().__init__()
        self.epsilon = epsilon

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        flattened = x.flatten(start_dim=2)                                   # [B, C, H*W]
        channel_mean = flattened.mean(dim=-1)                                # [B, C]
        channel_var = flattened.var(dim=-1, unbiased=False)                  # [B, C]
        channel_std = torch.sqrt(channel_var + self.epsilon)                 # [B, C]
        return torch.cat([channel_mean, channel_std], dim=1)                 # [B, 2C]

class MaskedPooling(nn.Module):
    """
    Masked global pooling over (frequency, time). Ignores time frames beyond each
    sample's valid (unpadded) length, so zero-padding introduced when batching
    variable-length unvoiced-fragment windows (UNVOICED_FRAGMENT_PAD_TO_WINDOW_ENABLED=False)
    never contributes to the pooled embedding.
    """
    def __init__(self, pooling_type=POOLING_TYPE, epsilon=POOLING_STD_EPSILON):
        super().__init__()
        self.pooling_type = pooling_type
        self.epsilon = epsilon

    def forward(self, x: torch.Tensor, valid_time_lengths: torch.Tensor) -> torch.Tensor:
        # x: [B, C, H, W] ; valid_time_lengths: [B] (valid W, in backbone-output resolution)
        batch_size, num_channels, freq_bins, time_frames = x.shape
        time_index = torch.arange(time_frames, device=x.device).unsqueeze(0)              # [1, W]
        time_mask = (time_index < valid_time_lengths.unsqueeze(1)).to(x.dtype)            # [B, W]
        spatial_mask = time_mask.view(batch_size, 1, 1, time_frames)                      # [B,1,1,W]
        valid_element_count = (spatial_mask.sum(dim=-1) * freq_bins).clamp(min=1.0)       # [B,1,1]

        masked_x = x * spatial_mask
        channel_mean = masked_x.flatten(start_dim=2).sum(dim=-1) / valid_element_count.squeeze(-1)

        if self.pooling_type == "gap":
            return channel_mean  # [B, C]

        squared_deviation = ((x - channel_mean.unsqueeze(-1).unsqueeze(-1)) ** 2) * spatial_mask
        channel_var = squared_deviation.flatten(start_dim=2).sum(dim=-1) / valid_element_count.squeeze(-1)
        channel_std = torch.sqrt(channel_var + self.epsilon)
        return torch.cat([channel_mean, channel_std], dim=1)  # [B, 2C]

class Neck(nn.Sequential):
    def __init__(self, out_dim, dropout_fc=0.4, in_channels=BACKBONE_OUT_CHANNELS,
                 pooling_type=POOLING_TYPE):
        if pooling_type == "gap":
            pooling_layers = [nn.AdaptiveAvgPool2d(1), nn.Flatten()]
            fc_in_features = in_channels
        elif pooling_type == "statistical":
            pooling_layers = [StatisticsPooling(), nn.Identity()]
            fc_in_features = 2 * in_channels
        else:
            raise ValueError(f"Unsupported POOLING_TYPE: {pooling_type}")

        super().__init__(
            *pooling_layers,
            nn.Linear(fc_in_features, 1024),
            nn.ReLU(),
            nn.Dropout(dropout_fc),
            nn.Linear(1024, 256),
            nn.ReLU(),
            nn.Dropout(dropout_fc),
            nn.Linear(256, out_dim),
        )

def compute_backbone_output_time_length(input_time_lengths: torch.Tensor) -> torch.Tensor:
    """
    Replicates, in tensor form, the exact time-axis downsampling performed by
    the Backbone's two nn.MaxPool2d(2, ceil_mode=BACKBONE_POOL_CEIL_MODE)
    layers, matching ceil/floor rounding to BACKBONE_POOL_CEIL_MODE so the
    mask length never diverges from the Backbone's actual output length.
    Clamped to a minimum of 1 valid frame as a safety net.
    """
    time_lengths = input_time_lengths
    for _ in range(2):
        if BACKBONE_POOL_CEIL_MODE:
            time_lengths = torch.div(time_lengths + 1, 2, rounding_mode="floor")
        else:
            time_lengths = torch.div(time_lengths, 2, rounding_mode="floor")
    return time_lengths.clamp(min=1)

class EmbeddingNet(nn.Module):
    def __init__(self, out_dim, dropout_conv=0.1, dropout_fc=0.1, normalize=True,
                 pooling_type=POOLING_TYPE):
        super().__init__()
        self.backbone = Backbone(dropout_conv=dropout_conv)
        self.neck = Neck(out_dim, dropout_fc=dropout_fc, pooling_type=pooling_type)
        self.normalize = normalize
        self._init_weights()

    def _init_weights(self):
        for m in self.modules():
            if isinstance(m, (nn.Conv2d, nn.Linear)):
                nn.init.kaiming_normal_(m.weight, nonlinearity='relu')
                if m.bias is not None:
                    nn.init.zeros_(m.bias)
            elif isinstance(m, nn.GroupNorm):
                nn.init.ones_(m.weight)
                nn.init.zeros_(m.bias)

    def forward(self, x, valid_input_time_lengths=None):
        x = self.neck(self.backbone(x))
        if self.normalize:
            x = F.normalize(x, p=2, dim=1)
        return x

# To load the model if it was already trained before
def load_model_and_state(output_path, run_name, device,
                          out_dim=OUT_DIM, dropout_conv=DROPOUT_CONV, dropout_fc=DROPOUT_FC,
                          needs_history=True):
    """
    Ensures that 'model', 'global_mean', 'global_std' and (optionally)
    'history' exist in the global namespace, regardless of the order in
    which the notebook cells were executed.
    - If they already exist in globals(), reuse them (no retraining or
      reloading from disk).
    - If they don't exist, load them from the files the notebook already
      saves.
    - Always puts the model on the correct device before returning it.
    """
    globals_dict = globals()

    if 'model' not in globals_dict:
        model_path = os.path.join(output_path, f"siamese_model_{run_name}.pth")
        if not os.path.exists(model_path):
            raise FileNotFoundError(f"Model not found at {model_path}")
        checkpoint = torch.load(model_path, map_location='cpu')
        local_model = EmbeddingNet(out_dim=out_dim, dropout_conv=dropout_conv, dropout_fc=dropout_fc)
        local_model.load_state_dict(checkpoint['model_state_dict'])
    else:
        local_model = globals_dict['model']

    local_model.to(device)

    local_history = globals_dict.get('history')
    if needs_history and local_history is None:
        if os.path.exists(final_history_path):
            with open(final_history_path, "rb") as f:
                local_history = pickle.load(f)
        else:
            print(f"Notice: history not found at {final_history_path}, returning None")

    return local_model, local_history

def ensure_device(model, device):
    if next(model.parameters()).device != device:
        model.to(device)
    return model

###########################################
"""Diagnostic of the MPerClassSampler"""
###########################################

def verify_batch_sampler(train_loader, id_to_device=None, expected_m=M_PER_CLASS):
    """
    Verifies that each batch has at least 'expected_m' samples per class,
    a necessary condition for the miner to find complete positive pairs.
    """
    #specs, labels = next(iter(train_loader))
    batch = next(iter(train_loader))
    specs, labels = batch[0], batch[1]
    labels_np = labels.cpu().numpy()

    values, counts = np.unique(labels_np, return_counts=True)

    print(f"Total batch size: {len(labels_np)}")
    print(f"Distinct classes in the batch: {len(values)}")
    print(f"{'Class':<10}{'Name':<20}{'# Samples':>12}")
    print("-" * 42)

    has_problem = False
    for v, c in zip(values, counts):
        name = id_to_device[v] if id_to_device else str(v)
        flag = "  <-- insufficient" if c < expected_m else ""
        if c < expected_m:
            has_problem = True
        print(f"{v:<10}{name:<20}{c:>12}{flag}")

    if has_problem:
        print(f"\n There are classes with fewer than {expected_m} samples: "
              f"the miner won't be able to form complete positive pairs for them.")
    else:
        print(f"\n All classes have at least {expected_m} samples per batch.")

    return dict(zip(values.tolist(), counts.tolist()))

