def train_with_kfold(device_to_label, output_path, device,
                      n_splits=N_SPLITS, out_dim=OUT_DIM, epochs=EPOCHS, lr=LR):
    """
    Version of K-Fold that does NOT recompute mel-spectrograms.
    Loads each fold already processed (fold_1.pkl, fold_2.pkl, ...) generated
    previously in the CPU notebook with cache_folds().
    """

    fold_histories = []
    fold_metrics = []
    set_all_seeds(RANDOM_SEED)
    for fold in range(n_splits):
        print(f"\n{'='*50}")
        print(f"  FOLD {fold+1}/{n_splits}")
        print(f"{'='*50}")

        fold_path = os.path.join(output_path, f"fold_{fold+1}.pkl")
        with open(fold_path, "rb") as f:
            fold_data = pickle.load(f)
        train_windows, val_windows = fold_data["train"], fold_data["val"]

        # Normalization computed only over this fold's train set
        # sum_value, sum_squares, total_count = 0.0, 0.0, 0
        # for v in train_windows:
        #     feature = v['spectral_feature']
        #     sum_value += feature.sum()
        #     sum_squares += (feature.astype(np.float64) ** 2).sum()
        #     total_count += feature.size

        # fold_mean = float(sum_value / total_count)
        # fold_std = float(np.sqrt(max(sum_squares / total_count - fold_mean**2, 0.0)))

        # Datasets and Loaders

        train_dataset = EmbeddingExtractionDataset(train_windows, device_to_label)#, fold_mean, fold_std)
        val_dataset = EmbeddingExtractionDataset(val_windows, device_to_label)#, fold_mean, fold_std)

        fold_train_labels = [device_to_label[v['device_b']] for v in train_windows]
        fold_sampler = MPerClassSampler(fold_train_labels, m=M_PER_CLASS, batch_size=BATCH_SIZE,
                                         length_before_new_iter=len(fold_train_labels))

        fold_train_loader = DataLoader(train_dataset, batch_size=BATCH_SIZE, sampler=fold_sampler, collate_fn=collate_variable_length_spectrograms)
        fold_val_loader = DataLoader(val_dataset, batch_size=BATCH_SIZE, shuffle=False, collate_fn=collate_variable_length_spectrograms)
        batch_counts = verify_batch_sampler(fold_train_loader, id_to_device)  # inside train_with_kfold, after fold_train_loader (test once and remove)
        # Fresh model per fold
        fold_model = EmbeddingNet(out_dim=out_dim, dropout_conv=DROPOUT_CONV, dropout_fc=DROPOUT_FC)

        fold_optimizer, fold_loss_fn, pml_adapter = build_metric_learning_components(
            fold_model, lr=lr, out_dim=out_dim, device=device
        )
        fold_scheduler = torch.optim.lr_scheduler.ReduceLROnPlateau(
            fold_optimizer, mode='min', factor=LR_SCHEDULER_FACTOR, patience=LR_SCHEDULER_PATIENCE,
            threshold=LR_SCHEDULER_THRESHOLD, threshold_mode=LR_SCHEDULER_THRESHOLD_MODE,
            cooldown=LR_SCHEDULER_COOLDOWN, min_lr=LR_SCHEDULER_MIN_LR
        )
        fold_trainer = Trainer()
        fold_trainer.set_adapter(pml_adapter)
        fold_checkpoint_path = os.path.join(output_path, f"checkpoint_fold_{fold+1}_{run_name}.pt")
        fold_best_checkpoint_path = os.path.join(output_path, f"best_fold_{fold+1}_{run_name}.pt")
        if not RESUME_FROM_CHECKPOINT and os.path.exists(fold_checkpoint_path):
          os.remove(fold_checkpoint_path)
        history = fold_trainer.fit(
            model=fold_model,
            loader=fold_train_loader,
            valid_loader=fold_val_loader,
            loss_fn=fold_loss_fn,
            optimizer=fold_optimizer,
            epochs=epochs,
            scheduler=fold_scheduler,
            early_stopping_patience=EARLY_STOPPING_PATIENCE,
            early_stopping_min_delta=EARLY_STOPPING_MIN_DELTA,
            grad_clip_norm=GRAD_CLIP_NORM, checkpoint_path=fold_checkpoint_path,
            best_checkpoint_path=fold_best_checkpoint_path,
            checkpoint_every=SAVE_CHECKPOINT_EVERY_N_EPOCHS,
        )
        # k-NN evaluation
        #device = fold_trainer._device
        fold_model.to(device)
        if os.path.exists(fold_best_checkpoint_path):
            best_checkpoint = torch.load(fold_best_checkpoint_path, map_location=device)
            fold_model.load_state_dict(best_checkpoint['model_state_dict'])
            print(f"Fold {fold+1}: using best checkpoint "
                  f"(epoch {best_checkpoint['epoch']+1}, valid_loss={best_checkpoint['valid_loss']:.4f})")
        train_embedding_loader = DataLoader(
            EmbeddingExtractionDataset(train_windows, device_to_label),#, fold_mean, fold_std),
            batch_size=BATCH_SIZE, collate_fn=collate_variable_length_spectrograms
        )
        val_embedding_loader = DataLoader(
            EmbeddingExtractionDataset(val_windows, device_to_label),#, fold_mean, fold_std),
            batch_size=BATCH_SIZE, collate_fn=collate_variable_length_spectrograms
        )

        train_embeddings, train_labels = extract_embeddings(fold_model, train_embedding_loader, device)
        val_embeddings, val_labels = extract_embeddings(fold_model, val_embedding_loader, device)

        print(f"train embeddings: {len(train_embeddings)}")
        print(f"val_embeddings: {len(val_embeddings)}")
        knn_model = KNeighborsClassifier(n_neighbors=KNN_NEIGHBORS, metric="euclidean")
        knn_model.fit(train_embeddings.numpy(), train_labels.numpy())
        #knn_model.fit(reference_embeddings.numpy(), reference_labels.numpy())
        predictions = knn_model.predict(val_embeddings.numpy())
        knn_accuracy = accuracy_score(val_labels.numpy(), predictions)

        plot_knn_confusion_matrix(
        val_labels.numpy(), predictions, id_to_device,
        title=f"kNN Confusion Matrix — Fold {fold+1}",
        file_name=f"cm_knn_fold_{fold+1}.png"
        )
        print(f"Fold {fold+1} — kNN Accuracy: {knn_accuracy:.4%}")

        fold_histories.append(history)
        fold_metrics.append({
            'fold': fold + 1,
            'knn_accuracy': knn_accuracy,
            'final_val_loss': history['valid_loss'][-1] if history['valid_loss'] else best_checkpoint['valid_loss'],
            #'fold_mean': fold_mean,
            #'fold_std': fold_std,
        })

        del train_windows, val_windows
        del train_dataset, val_dataset, fold_train_loader, fold_val_loader
        del fold_model, fold_optimizer, fold_scheduler, fold_loss_fn, fold_trainer, pml_adapter  #For ArcFace and CosFace loss executions
        del train_embeddings, train_labels, val_embeddings, val_labels, train_embedding_loader, val_embedding_loader
        torch.cuda.empty_cache()
        gc.collect()
    return fold_histories, fold_metrics

def build_final_model_holdout_windows(audio_items,
                                      validation_fraction=FINAL_MODEL_VALIDATION_FRACTION,
                                      stratify_keys=KFOLD_STRATIFY_KEYS,
                                      seed=RANDOM_SEED,
                                      cache_path=final_holdout_windows_path):
    """
    Splits raw training audios into train/validation subsets at AUDIO level
    (stratified by device/condition) and windows each subset independently,
    preventing window-level leakage between the two. Validation windows are
    generated without jitter. Result is cached to disk.
    """
    if os.path.exists(cache_path):
        print(f"Final-model holdout windows already exist, loading from {cache_path}")
        with open(cache_path, "rb") as f:
            cached = pickle.load(f)
        return cached["train"], cached["validation"]

    stratification_labels = build_stratification_labels(audio_items, stratify_keys)
    train_audios, validation_audios = train_test_split(
        audio_items, test_size=validation_fraction,
        stratify=stratification_labels, random_state=seed,
    )
    validate_fold_composition(-1, train_audios, validation_audios,
                              stratify_keys=stratify_keys, min_count=MIN_VIABLE)

    random.seed(seed)
    train_windows = generate_train_val_windows(train_audios, apply_jitter=APPLY_JITTER_TRAIN)
    validation_windows = generate_train_val_windows(
        validation_audios, apply_jitter=APPLY_JITTER_EVAL, is_validation=True
    )

    with open(cache_path, "wb") as f:
        pickle.dump({"train": train_windows, "validation": validation_windows}, f,
                    protocol=pickle.HIGHEST_PROTOCOL)
    print(f"Final-model holdout windows saved to {cache_path}")
    return train_windows, validation_windows

###########################################
"""Final Model — trained with ALL data FROM CACHE (GPU only)"""
###########################################
# After K-Fold, train the definitive model with all of raw_train_audios.
# Hyperparameters were already validated by K-Fold, there is no val set here.


def train_final_model(output_path, device_to_label,
                       out_dim=OUT_DIM, epochs=EPOCHS, lr=LR):
    """
    Trains the definitive model using ALL training audio files.
    Loads the already-windowed dataset (features already extracted on CPU)
    instead of recomputing it, so this step only uses GPU.
    """
    # Load already processed dataset (generated in the CPU notebook)

    # Global normalization (saved for inference)
    # Global normalization (without duplicating the dataset in memory)
    # sum_value = 0.0
    # sum_squares = 0.0
    # total_count = 0
    # for v in final_training_dataset:
    #     feature = v['spectral_feature']
    #     sum_value += feature.sum()
    #     sum_squares += (feature.astype(np.float64) ** 2).sum()
    #     total_count += feature.size

    # global_mean = float(sum_value / total_count)
    # global_variance = float(sum_squares / total_count - global_mean ** 2)
    # global_std = float(np.sqrt(max(global_variance, 0.0)))
    # print(f"Global mean: {global_mean:.4f} | Global std: {global_std:.4f}")

    if FINAL_MODEL_USE_VALIDATION_HOLDOUT:
        train_windows, validation_windows = build_final_model_holdout_windows(raw_train_audios)
    else:
        train_windows, validation_windows = final_training_dataset, None

    train_dataset = EmbeddingExtractionDataset(train_windows, device_to_label)
    final_train_labels = [device_to_label[v['device_b']] for v in train_windows]
    final_sampler = MPerClassSampler(final_train_labels, m=M_PER_CLASS, batch_size=BATCH_SIZE,
                                      length_before_new_iter=len(final_train_labels))
    train_loader = DataLoader(train_dataset, batch_size=BATCH_SIZE, sampler=final_sampler, collate_fn=collate_variable_length_spectrograms)

    valid_loader = None
    if validation_windows is not None:
        valid_loader = DataLoader(
            EmbeddingExtractionDataset(validation_windows, device_to_label),
            batch_size=BATCH_SIZE, shuffle=False, collate_fn=collate_variable_length_spectrograms
        )

    set_all_seeds(RANDOM_SEED)
    model = EmbeddingNet(out_dim=out_dim, dropout_conv=DROPOUT_CONV, dropout_fc=DROPOUT_FC)

    optimizer, loss_fn, pml_adapter = build_metric_learning_components(
        model, lr=lr, out_dim=out_dim, device=device
    )

    trainer = Trainer()
    trainer.set_adapter(pml_adapter)

    fit_kwargs = dict(
        model=model,
        loader=train_loader,
        valid_loader=valid_loader,
        loss_fn=loss_fn,
        optimizer=optimizer,
        epochs=epochs,
        grad_clip_norm=GRAD_CLIP_NORM,
        checkpoint_path=final_checkpoint_path,
        checkpoint_every=SAVE_CHECKPOINT_EVERY_N_EPOCHS,
    )
    if valid_loader is not None:
        fit_kwargs.update(
            scheduler=torch.optim.lr_scheduler.ReduceLROnPlateau(
                optimizer, mode='min', factor=LR_SCHEDULER_FACTOR, patience=LR_SCHEDULER_PATIENCE,
                threshold=LR_SCHEDULER_THRESHOLD, threshold_mode=LR_SCHEDULER_THRESHOLD_MODE,
                cooldown=LR_SCHEDULER_COOLDOWN, min_lr=LR_SCHEDULER_MIN_LR
            ),
            early_stopping_patience=EARLY_STOPPING_PATIENCE,
            early_stopping_min_delta=EARLY_STOPPING_MIN_DELTA,
            best_checkpoint_path=final_best_checkpoint_path,
        )

    history = trainer.fit(**fit_kwargs)

    # Restore the best-validation weights (same behavior as the K-Fold loop)
    if valid_loader is not None and os.path.exists(final_best_checkpoint_path):
        best_checkpoint = torch.load(final_best_checkpoint_path, map_location=device)
        model.load_state_dict(best_checkpoint['model_state_dict'])
        print(f"Final model: using best checkpoint "
              f"(epoch {best_checkpoint['epoch'] + 1}, valid_loss={best_checkpoint['valid_loss']:.4f})")

    return model, history, trainer._device

