def visualize_kfold_results(fold_histories, fold_metrics):
    num_folds = len(fold_metrics)
    accuracies = [m['knn_accuracy'] for m in fold_metrics]
    losses = [m['final_val_loss'] for m in fold_metrics]

    print("\n===== K-FOLD SUMMARY =====")
    for m in fold_metrics:
        print(f"Fold {m['fold']}: kNN={m['knn_accuracy']:.4%} | val_loss={m['final_val_loss']:.4f}")
    print(f"\nkNN Accuracy: {np.mean(accuracies):.4%} ± {np.std(accuracies):.4%}")
    print(f"Val Loss:     {np.mean(losses):.4f} ± {np.std(losses):.4f}")

    # Loss plot per fold
    fig, axes = plt.subplots(1, 2, figsize=(14, 5))

    for i, history in enumerate(fold_histories):
        axes[0].plot(history['train_loss'], label=f'Fold {i+1}', alpha=0.7)
    axes[0].set_title('Train Loss per Fold')
    axes[0].set_xlabel('Epoch')
    axes[0].legend()
    axes[0].grid(True, alpha=0.3)

    axes[1].bar(range(1, num_folds + 1), accuracies, color='steelblue', alpha=0.7)
    axes[1].axhline(np.mean(accuracies), color='red', linestyle='--',
                     label=f'Mean: {np.mean(accuracies):.4%}')
    axes[1].set_title('kNN Accuracy per Fold')
    axes[1].set_xlabel('Fold')
    axes[1].set_ylabel('Accuracy')
    axes[1].legend()
    axes[1].grid(True, alpha=0.3)

    plt.tight_layout()
    plt.show()

def plot_knn_confusion_matrix(y_true, y_pred, id_to_device, title, file_name,
                               output_path=output_path, normalize=CM_NORMALIZE):
    present_classes = sorted(set(y_true) | set(y_pred))
    class_names_list = [id_to_device[c] for c in present_classes]

    confusion_mat = confusion_matrix(y_true, y_pred, labels=present_classes, normalize=normalize)

    fig, ax = plt.subplots(figsize=(max(8, len(class_names_list)*0.6), max(6, len(class_names_list)*0.5)))
    disp = ConfusionMatrixDisplay(confusion_matrix=confusion_mat, display_labels=class_names_list)
    disp.plot(ax=ax, xticks_rotation=90, values_format=".2f" if normalize else "d", colorbar=True)
    ax.set_title(title, fontweight='bold')
    plt.tight_layout()

    output_file_path = os.path.join(output_path, file_name)
    plt.savefig(output_file_path, dpi=FIGURE_DPI, bbox_inches='tight')
    plt.show()
    print(f"Confusion matrix saved to {output_file_path}")
    return confusion_mat, output_file_path

