def plot_kfold_train_loss_mean_std(fold_histories, output_path=kfold_train_loss_stats_png_path):
    """
    Aggregates the per-epoch train loss across all folds and plots the
    mean curve with a shaded +/- 1 standard deviation band. Folds are
    aligned by epoch index; if folds stopped early (early stopping) at
    different epochs, the curve is truncated to the shortest fold so the
    mean/std at every epoch is computed over the same number of folds.
    """
    train_loss_per_fold = [np.asarray(history['train_loss'], dtype=np.float64) for history in fold_histories]
    min_common_epochs = min(len(loss_curve) for loss_curve in train_loss_per_fold)

    if min_common_epochs < max(len(loss_curve) for loss_curve in train_loss_per_fold):
        print(f"Note: folds have different lengths due to early stopping; "
              f"truncating to the shortest common length ({min_common_epochs} epochs).")

    train_loss_matrix = np.stack([loss_curve[:min_common_epochs] for loss_curve in train_loss_per_fold], axis=0)
    epoch_mean = train_loss_matrix.mean(axis=0)
    epoch_std = train_loss_matrix.std(axis=0)
    epochs_range = np.arange(1, min_common_epochs + 1)

    fig, ax = plt.subplots(figsize=(9, 6))
    ax.plot(epochs_range, epoch_mean, color='steelblue', linewidth=2, label='Mean train loss')
    ax.fill_between(epochs_range, epoch_mean - epoch_std, epoch_mean + epoch_std,
                     color='steelblue', alpha=0.25, label='± 1 std. dev.')

    for fold_index, loss_curve in enumerate(train_loss_per_fold):
        ax.plot(np.arange(1, len(loss_curve) + 1), loss_curve, color='gray',
                 linewidth=0.8, alpha=0.4, label='Individual folds' if fold_index == 0 else None)

    ax.set_title(f'K-Fold Train Loss — Mean ± Std. Dev. (n_splits={len(fold_histories)})', fontweight='bold')
    ax.set_xlabel('Epoch')
    ax.set_ylabel('Train Loss')
    ax.legend()
    ax.grid(True, alpha=0.3)
    plt.tight_layout()

    plt.savefig(output_path, dpi=FIGURE_DPI, bbox_inches='tight')
    plt.show()
    print(f"K-Fold train loss mean/std plot saved to {output_path}")

    return epoch_mean, epoch_std

kfold_train_loss_mean, kfold_train_loss_std = plot_kfold_train_loss_mean_std(fold_histories)

###########################################
"""K-Fold kNN Accuracy — Mean and Standard Deviation Across Folds"""
