def plot_kfold_knn_accuracy_mean_std(fold_metrics, output_path=kfold_knn_accuracy_stats_png_path):
    """
    Summarizes the per-fold kNN validation accuracy with a bar chart:
    one bar per fold plus a reference bar for the aggregate mean, with
    the standard deviation shown as an error bar on the mean.
    """
    fold_labels = [f"Fold {m['fold']}" for m in fold_metrics]
    fold_accuracies = np.array([m['knn_accuracy'] for m in fold_metrics], dtype=np.float64)

    accuracy_mean = fold_accuracies.mean()
    accuracy_std = fold_accuracies.std()

    bar_labels = fold_labels + ['Mean']
    bar_values = np.append(fold_accuracies, accuracy_mean)
    bar_errors = np.append(np.zeros_like(fold_accuracies), accuracy_std)
    bar_colors = ['steelblue'] * len(fold_accuracies) + ['darkorange']

    fig, ax = plt.subplots(figsize=(8, 6))
    bars = ax.bar(bar_labels, bar_values, yerr=bar_errors, color=bar_colors, alpha=0.85, capsize=8)

    for bar, value in zip(bars, bar_values):
        ax.text(bar.get_x() + bar.get_width() / 2, value + 0.02, f'{value:.4%}',
                ha='center', fontweight='bold', fontsize=9)

    ax.set_ylabel('kNN Accuracy')
    ax.set_ylim(0, 1.05)
    ax.set_title(f'K-Fold kNN Accuracy — Mean ± Std. Dev. (n_splits={len(fold_metrics)})\n'
                 f'Mean: {accuracy_mean:.4%} ± {accuracy_std:.4%}', fontweight='bold')
    ax.grid(True, axis='y', alpha=0.3)
    plt.tight_layout()

    plt.savefig(output_path, dpi=FIGURE_DPI, bbox_inches='tight')
    plt.show()
    print(f"K-Fold kNN accuracy mean/std plot saved to {output_path}")

    return accuracy_mean, accuracy_std

kfold_knn_accuracy_mean, kfold_knn_accuracy_std = plot_kfold_knn_accuracy_mean_std(fold_metrics)

