def plot_lr_history(fold_histories, final_history=None, output_path=output_path):
    num_folds = len(fold_histories)
    num_panels = num_folds + (1 if final_history is not None else 0)

    fig, axes = plt.subplots(1, num_panels, figsize=(6*num_panels, 5), sharey=True)
    if num_panels == 1:
        axes = [axes]

    def _plot_lr(ax, lr_history, title):
        epochs_range = range(1, len(lr_history) + 1)
        ax.plot(epochs_range, lr_history, color='steelblue', linewidth=2, marker='o', markersize=3)

        # Mark the epochs where the LR changed (that's where the scheduler acted)
        for i in range(1, len(lr_history)):
            if lr_history[i] != lr_history[i - 1]:
                ax.axvline(x=i + 1, color='red', linestyle='--', alpha=0.6)
                ax.scatter([i + 1], [lr_history[i]], color='red', s=60, zorder=5)

        ax.set_title(title)
        ax.set_xlabel('Epoch')
        ax.set_ylabel('Learning Rate')
        ax.set_yscale('log')
        ax.grid(True, alpha=0.3, which='both')

    for i, history in enumerate(fold_histories):
        _plot_lr(axes[i], history['lr'], f'Fold {i+1}')

    if final_history is not None:
        _plot_lr(axes[-1], final_history['lr'], 'Final Model')

    plt.suptitle('Learning Rate History (ReduceLROnPlateau)', fontsize=14, fontweight='bold', y=1.02)
    plt.tight_layout()

    output_file_path = os.path.join(output_path, "lr_history.png")
    plt.savefig(output_file_path, dpi=FIGURE_DPI, bbox_inches='tight')
    plt.show()
    print(f"LR plot saved to {output_file_path}")
plot_lr_history(fold_histories)

