###########################################
"""Train vs Test accuracy gap (kNN)"""
###########################################

def plot_train_test_accuracy_gap(train_embeddings, train_labels, val_embeddings, val_labels,
                                   knn_neighbors=KNN_NEIGHBORS, output_path=output_path):
    """
    Train accuracy is computed via cross-validation WITHIN the train set
    itself (not with knn.predict directly on train, because there each
    point would find itself as its nearest neighbor, giving an artificial
    ~100%).
    """
    knn_model = KNeighborsClassifier(n_neighbors=knn_neighbors, metric='euclidean')

    cv_splitter = StratifiedKFold(n_splits=N_SPLITS_CV_GAP, shuffle=True, random_state=RANDOM_SEED)
    train_cv_predictions = cross_val_predict(knn_model, train_embeddings.numpy(), train_labels.numpy(), cv=cv_splitter)
    train_cv_accuracy = cross_val_score(knn_model, train_embeddings.numpy(), train_labels.numpy(), cv=cv_splitter, scoring='accuracy')
    train_accuracy_mean = train_cv_accuracy.mean()
    train_accuracy_std = train_cv_accuracy.std()

    # Real test accuracy: kNN model trained with ALL of train, evaluated on never-seen test
    knn_model.fit(train_embeddings.numpy(), train_labels.numpy())
    test_predictions = knn_model.predict(val_embeddings.numpy())
    test_accuracy = accuracy_score(val_labels.numpy(), test_predictions)
    plot_knn_confusion_matrix(
    train_labels.numpy(), train_cv_predictions, id_to_device,
    title="kNN Confusion Matrix — Train (5-fold CV)",
    file_name=f"cm_knn_train_cv_{run_name}.png"
    )
    fig, ax = plt.subplots(figsize=(7, 6))
    bars = ax.bar(['Train\n(5-fold cross-val)', 'Test\n(never seen)'],
                     [train_accuracy_mean, test_accuracy],
                     yerr=[train_accuracy_std, 0],
                     color=['steelblue', 'darkorange'], alpha=0.8, capsize=8)
    for bar, value in zip(bars, [train_accuracy_mean, test_accuracy]):
        ax.text(bar.get_x() + bar.get_width()/2, value + 0.02, f'{value:.4%}',
                ha='center', fontweight='bold')

    ax.set_ylabel('kNN Accuracy')
    ax.set_ylim(0, 1.05)
    ax.set_title(f'Train vs Test Gap — kNN (k={knn_neighbors})\n'
                 f'Difference: {(train_accuracy_mean - test_accuracy):.4%}',
                 fontweight='bold')
    ax.grid(True, axis='y', alpha=0.3)
    plt.tight_layout()

    output_file_path = os.path.join(output_path, "gap_train_test_accuracy.png")
    plt.savefig(output_file_path, dpi=FIGURE_DPI, bbox_inches='tight')
    plt.show()

    print(f"Train accuracy (5-fold CV): {train_accuracy_mean:.4%} ± {train_accuracy_std:.4%}")
    print(f"Test accuracy (real):       {test_accuracy:.4%}")
    print(f"Gap (train - test):         {(train_accuracy_mean - test_accuracy):.4%}")
    print(f"Plot saved to {output_file_path}")

    return train_accuracy_mean, test_accuracy

