def count_parameters(model, detail=True):
    total_params = 0
    trainable_params = 0

    if detail:
        print(f"{'Layer':<40}{'Shape':<20}{'# Parameters':>15}")
        print("-" * 75)

    for name, param in model.named_parameters():
        num_params = param.numel()
        total_params += num_params
        if param.requires_grad:
            trainable_params += num_params
        if detail:
            print(f"{name:<40}{str(tuple(param.shape)):<20}{num_params:>15,}")

    print("-" * 75)
    print(f"Total parameters:       {total_params:,}")
    print(f"Trainable parameters:    {trainable_params:,}")
    print(f"Non-trainable parameters: {total_params - trainable_params:,}")
    return total_params, trainable_params

count_parameters(model)

def count_flops_macs(model, input_shape=(1, 1, freq_bins, n_frames), device='cpu'):
    """
    Computes model FLOPs and MACs without modifying it.
    input_shape: (batch, channels, length) — adjust 128 to the actual size
                 of your spectral_feature (n_fft//2 + 1, check the real shape).
    """
    cpu_model = model.to('cpu')  # thop is more stable on CPU
    cpu_model.eval()

    dummy_input = torch.randn(input_shape)

    macs, params = profile(cpu_model, inputs=(dummy_input,), verbose=False)
    macs_formatted, params_formatted = clever_format([macs, params], "%.4f")

    flops = macs * 2  # 1 MAC ≈ 2 FLOPs

    print(f"Test input: {input_shape}")
    print(f"MACs:   {macs_formatted}  ({macs:,.0f} exact MACs)")
    print(f"FLOPs:  ≈{flops:,.0f}  (2 × MACs)")
    print(f"Params: {params_formatted}  ({int(params):,} exact parameters)")

    model.to(device)  # return the model to its original device
    return macs, flops, params

# Usage: adjust input_shape according to the actual shape of your spectral_feature
macs, flops, params = count_flops_macs(model, input_shape=(1, 1, freq_bins, n_frames), device=device)

