test_result = generate_splicing_pair(test_audio_a, test_audio_b)

spliced_test_audio = test_result['audio']
real_cut_point = test_result['cut_point']
real_cut_time = test_result['cut_time']

print(f"Real cut point: sample {real_cut_point} - {real_cut_time:.4f} seconds")

# Pass to the forensic report

forensic_report_result = generate_forensic_report(
    suspect_audio=spliced_test_audio,
    model=model,
    device=device,
    threshold=calibrated_threshold['audio'],
    #mean_global=global_mean,
    #std_global=global_std,
    compute_entropy_comparison=True,
    entropy_window=ENTROPY_LOCAL_WINDOW,
)
# check what the actual max distance obtained is
print(f"Max distance found: {forensic_report_result['max_distance']:.4f}")
print(f"Current threshold:  {forensic_report_result['threshold_used']:.4f}")
print(f"Detected splice?:    {forensic_report_result['has_splice']}")

# Compare what the model detected against reality

if forensic_report_result['has_splice']:
    time_error = abs(real_cut_time - forensic_report_result['splice_time_sec'])
    print(f"Model detected: splice at {forensic_report_result['splice_time_sec']:.4f}s")
    print(f"Error:          {time_error:.4f}s")
else:
    print(f"Model detected: AUTHENTIC AUDIO (did not exceed threshold {forensic_report_result['threshold_used']:.4f})")
    print(f"Max distance:   {forensic_report_result['max_distance']:.4f}")
if forensic_report_result.get('has_splice_entropy'):
    time_error_entropy = abs(real_cut_time - forensic_report_result['splice_time_sec_entropy'])
    print(f"Entropy-weighted candidate: splice at {forensic_report_result['splice_time_sec_entropy']:.4f}s")
    print(f"Error (entropy):            {time_error_entropy:.4f}s")
else:
    print(f"Entropy-weighted candidate: no distance above threshold ")
    print(f"(max distance = {forensic_report_result.get('max_distance_entropy', float('nan')):.4f})")

strategy_comparison_results = plot_filtering_strategy_comparison(
    distances=forensic_report_result['distances'],
    timestamps=forensic_report_result['timestamps'][1:],
    threshold=forensic_report_result['threshold_used'],
    ground_truth_time_s=real_cut_time,
    median_filter_kernel_size=WINDOW_LEVEL_MEDIAN_FILTER_KERNEL_SIZE,
    entropy_window=ENTROPY_LOCAL_WINDOW,
    output_path=output_path,
    run_name=eval_run_name,
)

