###########################################
"""TEST — IA-SPLICING SAMPLE (single-example forensic report, Euclidean & Manhattan)"""
###########################################
# Draws one AI-generated splice sample and runs the same single-audio forensic
# report used for the synthetic-splice TEST blocks above, comparing the
# detected splice instant against the ground-truth insertion boundaries
# reported in the sample's metadata (true_insert_start_s / true_insert_end_s).

ia_test_sample = random.choice(ia_splicing_dataset)

print(f"IA-splicing sample: {ia_test_sample['filename']} "
      f"(device={ia_test_sample['device']}, condition={ia_test_sample['condition']})")

ia_ground_truth_boundaries_s = (
    ia_test_sample['true_insert_start_s'],
    ia_test_sample['true_insert_end_s'],
)
print(f"Ground-truth insertion boundaries: "
      f"{ia_ground_truth_boundaries_s[0]:.4f}s -> {ia_ground_truth_boundaries_s[1]:.4f}s")


def _nearest_boundary_error_s(detected_time_s, boundaries_s):
    """Localization error against the closer of the two insertion boundaries."""
    return min(abs(detected_time_s - boundary_s) for boundary_s in boundaries_s)


def _run_ia_splicing_forensic_test(distance_metric, threshold, VI=None):
    forensic_result = generate_forensic_report(
        suspect_audio=ia_test_sample['audio'],
        model=model,
        device=device,
        threshold=threshold,
        compute_entropy_comparison=True,
        entropy_window=ENTROPY_LOCAL_WINDOW,
        use_pairwise_distance=True,
        distance_metric=distance_metric,
        VI=VI,
    )

    print(f"\n[{distance_metric.capitalize()}] Max distance found: {forensic_result['max_distance']:.4f}")
    print(f"[{distance_metric.capitalize()}] Current threshold:  {forensic_result['threshold_used']:.4f}")
    print(f"[{distance_metric.capitalize()}] Detected splice?:    {forensic_result['has_splice']}")

    if forensic_result['has_splice']:
        time_error = _nearest_boundary_error_s(forensic_result['splice_time_sec'], ia_ground_truth_boundaries_s)
        print(f"[{distance_metric.capitalize()}] Model detected: splice at {forensic_result['splice_time_sec']:.4f}s")
        print(f"[{distance_metric.capitalize()}] Error (nearest boundary): {time_error:.4f}s")
    else:
        print(f"[{distance_metric.capitalize()}] Model detected: AUTHENTIC AUDIO "
              f"(did not exceed threshold {forensic_result['threshold_used']:.4f})")
        print(f"[{distance_metric.capitalize()}] Max distance: {forensic_result['max_distance']:.4f}")

    if forensic_result.get('has_splice_entropy'):
        time_error_entropy = _nearest_boundary_error_s(
            forensic_result['splice_time_sec_entropy'], ia_ground_truth_boundaries_s
        )
        print(f"[{distance_metric.capitalize()}] Entropy-weighted candidate: "
              f"splice at {forensic_result['splice_time_sec_entropy']:.4f}s")
        print(f"[{distance_metric.capitalize()}] Error (entropy, nearest boundary): {time_error_entropy:.4f}s")
    else:
        print(f"[{distance_metric.capitalize()}] Entropy-weighted candidate: no distance above threshold "
              f"(max distance = {forensic_result.get('max_distance_entropy', float('nan')):.4f})")

    strategy_comparison_results = plot_filtering_strategy_comparison(
        distances=forensic_result['distances'],
        timestamps=forensic_result['timestamps'][1:],
        threshold=forensic_result['threshold_used'],
        ground_truth_time_s=ia_ground_truth_boundaries_s[0],   # primary boundary: genuine -> IA segment
        median_filter_kernel_size=WINDOW_LEVEL_MEDIAN_FILTER_KERNEL_SIZE,
        entropy_window=ENTROPY_LOCAL_WINDOW,
        output_path=output_path,
        run_name=f"ia_splicing_{distance_metric}_{eval_run_name}",
    )

    print(f"\n=== Strategy comparison summary (IA-splicing, {distance_metric.capitalize()}) ===")
    for strategy_name, strategy_metrics in strategy_comparison_results.items():
        print(f"{strategy_name:<45} error = {strategy_metrics['localization_error_s']:.4f}s "
              f"(detected at {strategy_metrics['detected_time_s']:.4f}s)")

    return forensic_result, strategy_comparison_results


ia_forensic_result_euclidean, ia_strategy_comparison_euclidean = _run_ia_splicing_forensic_test(
    distance_metric="euclidean", threshold=calibrated_threshold['audio'], VI=None,
)

ia_forensic_result_manhattan, ia_strategy_comparison_manhattan = _run_ia_splicing_forensic_test(
    distance_metric="manhattan", threshold=calibrated_threshold_manhattan['audio'], VI=None,
)

def report_unseen_class_balance(evaluation_results, distance_metric, requested_audios_per_class):
    """Warns when the unseen-set audio-level evaluation could not build balanced classes."""
    audio_results = evaluation_results['audio']
    n_authentic, n_spliced = audio_results['n_authentic'], audio_results['n_spliced']
    print(f"[{distance_metric}] authentic={n_authentic}/{requested_audios_per_class} | "
          f"spliced={n_spliced}/{requested_audios_per_class}")
    if n_authentic < requested_audios_per_class or n_spliced < requested_audios_per_class:
        print(f"WARNING [{distance_metric}]: classes are incomplete or imbalanced; "
              f"EER is not strictly comparable with a fully balanced run.")

