###########################################
"""Audio-Level Score Strategies — Median / Median + Entropy EER (calibrated on val, evaluated on unseen devices)"""
###########################################

def compute_audio_score_by_strategy(raw_distances, median_filter_kernel_size, entropy_window,
                                    epsilon=SCORE_STRATEGY_ENTROPY_EPSILON):
    """
    Derives one audio-level detection score per strategy from the SAME raw
    consecutive-window distance sequence (paired design):
      baseline       : max(raw distances)
      median         : max(median-filtered distances)
      median_entropy : max(median-filtered distances / local entropy)
    Higher score = stronger evidence of splicing (same convention as eer_audio_level).
    """
    filtered_distances = _apply_median_filter(raw_distances, median_filter_kernel_size)
    filtered_local_entropy = _local_distance_entropy(filtered_distances, entropy_window=entropy_window)
    return {
        "baseline":       float(raw_distances.max()),
        "median":         float(filtered_distances.max()),
        "median_entropy": float(np.max(filtered_distances / (filtered_local_entropy + epsilon))),
    }


def collect_audio_level_strategy_scores(audio_pool, model, device, n_audios,
                                        sr, win_sec, hop_sec, n_fft, hop_length_fft, top_db,
                                        median_filter_kernel_size, entropy_window,
                                        distance_metric="euclidean", VI=None):
    """
    Mirrors the sampling protocol of eer_evaluation.eer_audio_level (eligibility,
    duration equalization, edge margin, authentic sampling without replacement)
    but returns one score per strategy for every audio.

    Labels: 1 = authentic, 0 = spliced.
    """
    module = eer_evaluation_module
    min_edge_margin_samples = int(module.SPLICE_MIN_EDGE_MARGIN_WINDOWS * win_sec * sr)
    min_duration_samples = int(module.AUDIO_LEVEL_MIN_DURATION_WINDOWS * win_sec * sr)

    eligible_audios = [a for a in audio_pool if len(a['audio']) >= min_duration_samples]
    pool_devices = sorted(set(a['device'] for a in eligible_audios))
    if len(pool_devices) < 2:
        raise ValueError("Audio-level strategy evaluation requires eligible audios from at least 2 devices.")
    audios_by_device = {d: [a for a in eligible_audios if a['device'] == d] for d in pool_devices}

    common_length_samples = (min(len(a['audio']) for a in eligible_audios)
                             if module.AUDIO_LEVEL_EQUALIZE_DURATION else None)

    def _crop_to_common_length(audio_signal):
        return audio_signal if common_length_samples is None else audio_signal[:common_length_samples]

    def _score_signal(audio_signal):
        embeddings, _ = module._audio_embeddings(
            audio_signal, model, device=device, sr=sr, win_sec=win_sec, hop_sec=hop_sec,
            n_fft=n_fft, hop_length_fft=hop_length_fft,
        )
        raw_distances = module._consecutive_distances(embeddings, distance_metric=distance_metric, VI=VI)
        if len(raw_distances) == 0:
            return None
        return compute_audio_score_by_strategy(raw_distances, median_filter_kernel_size, entropy_window)

    scores_by_strategy = {key: [] for key in SCORE_STRATEGY_KEYS}
    labels = []

    def _register(strategy_scores, label):
        for key in SCORE_STRATEGY_KEYS:
            scores_by_strategy[key].append(strategy_scores[key])
        labels.append(label)

    n_per_class = n_audios // 2

    # Authentic audios
    for audio_info in random.sample(eligible_audios, min(n_per_class, len(eligible_audios))):
        strategy_scores = _score_signal(_crop_to_common_length(audio_info['audio']))
        if strategy_scores is not None:
            _register(strategy_scores, 1)

    # Spliced audios
    n_spliced_generated, n_attempts = 0, 0
    max_attempts = n_per_class * module.SPLICE_MAX_ATTEMPTS_FACTOR
    while n_spliced_generated < n_per_class and n_attempts < max_attempts:
        n_attempts += 1
        device_a, device_b = random.sample(pool_devices, 2)
        audio_a = _crop_to_common_length(random.choice(audios_by_device[device_a])['audio'])
        audio_b = _crop_to_common_length(random.choice(audios_by_device[device_b])['audio'])
        spliced_audio, _ = generate_simple_splicing(
            audio_a, audio_b, top_db=top_db, min_edge_margin_samples=min_edge_margin_samples,
        )
        if spliced_audio is None:
            continue
        strategy_scores = _score_signal(spliced_audio)
        if strategy_scores is None:
            continue
        _register(strategy_scores, 0)
        n_spliced_generated += 1

    if n_spliced_generated < n_per_class:
        print(f"WARNING [{distance_metric}]: only {n_spliced_generated}/{n_per_class} spliced audios generated "
              f"after {n_attempts} attempts; classes are imbalanced.")

    return ({key: np.asarray(values) for key, values in scores_by_strategy.items()},
            np.asarray(labels))


def evaluate_audio_score_strategies(calibration_pool, evaluation_pools, model, device, n_audios,
                                    sr, win_sec, hop_sec, n_fft, hop_length_fft, top_db,
                                    median_filter_kernel_size, entropy_window,
                                    distance_metric="euclidean", VI=None, seed=RANDOM_SEED):
    """
    For each score strategy: (1) freeze the EER-optimal threshold on
    `calibration_pool` (val_audios), (2) evaluate on every pool in
    `evaluation_pools` (dict name -> audio list) reporting EER, FAR and FRR
    at the frozen threshold, with bootstrap confidence intervals.
    """
    scoring_kwargs = dict(
        model=model, device=device, n_audios=n_audios, sr=sr, win_sec=win_sec, hop_sec=hop_sec,
        n_fft=n_fft, hop_length_fft=hop_length_fft, top_db=top_db,
        median_filter_kernel_size=median_filter_kernel_size, entropy_window=entropy_window,
        distance_metric=distance_metric, VI=VI,
    )

    set_all_seeds(seed)
    calibration_scores, calibration_labels = collect_audio_level_strategy_scores(calibration_pool, **scoring_kwargs)
    frozen_thresholds = {key: calculate_eer(calibration_scores[key], calibration_labels)[1]
                         for key in SCORE_STRATEGY_KEYS}

    # Calibration-stability CI of each strategy's EER-optimal threshold (val_audios only)
    frozen_threshold_intervals = {
        key: bootstrap_calibrated_threshold(calibration_scores[key], calibration_labels)
        for key in SCORE_STRATEGY_KEYS
    }
    print(f"\n[{distance_metric}] Frozen-threshold stability (calibration pool)")
    for key in SCORE_STRATEGY_KEYS:
        print(f"   {SCORE_STRATEGY_LABELS[key]}: "
              f"{format_confidence_interval(frozen_threshold_intervals[key], as_percent=False)}")

    results = {
        "distance_metric": distance_metric,
        "frozen_thresholds": frozen_thresholds,
        "frozen_threshold_bootstrap": frozen_threshold_intervals,
        "evaluation": {},
    }
    for pool_name, evaluation_pool in evaluation_pools.items():
        set_all_seeds(seed)
        evaluation_scores, evaluation_labels = collect_audio_level_strategy_scores(evaluation_pool, **scoring_kwargs)

        results["evaluation"][pool_name] = {}
        print(f"\n[{distance_metric} | {pool_name}] "
              f"authentic={int((evaluation_labels == 1).sum())} | spliced={int((evaluation_labels == 0).sum())}")
        for key in SCORE_STRATEGY_KEYS:
            frozen_threshold = frozen_thresholds[key]
            detection_intervals = bootstrap_detection_metrics(
                evaluation_scores[key], evaluation_labels, frozen_threshold)
            results["evaluation"][pool_name][key] = {
                "scores": evaluation_scores[key],
                "labels": evaluation_labels,
                "frozen_threshold": frozen_threshold,
                "eer": detection_intervals["eer"]["estimate"],
                "far": detection_intervals["far"]["estimate"],
                "frr": detection_intervals["frr"]["estimate"],
                "bootstrap": detection_intervals,
            }
            print(f"   {SCORE_STRATEGY_LABELS[key]} (thr={frozen_threshold:.4f})")
            for metric_name, interval in detection_intervals.items():
                print(f"      {metric_name.upper():<4} {format_confidence_interval(interval)}")
    return results


