###########################################
"""Audio-Level Score Strategies — Summary Table and EER/ROC Plots"""
###########################################

def build_strategy_eer_summary_table(strategy_eer_results, decimals=SUMMARY_TABLE_DECIMALS):
    """
    Flattens the nested output of evaluate_audio_score_strategies() into a
    tidy DataFrame (one row per distance metric x evaluation pool x strategy).
    EER / FAR / FRR are expressed in percent, each with its bootstrap CI bounds.
    """
    records = []
    for distance_metric, metric_results in strategy_eer_results.items():
        for pool_name, pool_results in metric_results["evaluation"].items():
            for strategy_key, strategy_result in pool_results.items():
                record = {
                    "distance_metric": distance_metric,
                    "pool": pool_name,
                    "strategy": SCORE_STRATEGY_LABELS[strategy_key],
                    "frozen_threshold": strategy_result["frozen_threshold"],
                }
                for detection_metric in ("eer", "far", "frr"):
                    interval = strategy_result["bootstrap"][detection_metric]
                    record[f"{detection_metric}_pct"] = 100.0 * interval["estimate"]
                    record[f"{detection_metric}_ci_lower_pct"] = 100.0 * interval["ci_lower"]
                    record[f"{detection_metric}_ci_upper_pct"] = 100.0 * interval["ci_upper"]
                records.append(record)
    return pd.DataFrame.from_records(records).round(decimals)


def plot_strategy_eer_comparison(strategy_eer_results, path_template=strategy_eer_png_template,
                                 strategy_keys=SCORE_STRATEGY_KEYS, dpi=FIGURE_DPI):
    """
    One figure per distance metric:
      Panel 0    : grouped bars of EER (with bootstrap CI error bars),
                   evaluation pools on the x-axis, one bar per score strategy.
      Panels 1..N: ROC curves of every strategy for each evaluation pool.
    Label convention of eer_evaluation.py (1 = authentic, 0 = spliced, higher
    score = more spliced) is handled by inverting the scores, exactly as
    calculate_eer() does.
    """
    colormap = matplotlib.colormaps["tab10"]
    saved_paths = {}

    for distance_metric, metric_results in strategy_eer_results.items():
        evaluation = metric_results["evaluation"]
        pool_names = list(evaluation.keys())
        n_strategies = len(strategy_keys)
        bar_width = 0.8 / n_strategies

        fig, axes = plt.subplots(1, 1 + len(pool_names), figsize=(6 * (1 + len(pool_names)), 6))

        # Panel 0: EER with bootstrap CI
        ax = axes[0]
        x_positions = np.arange(len(pool_names))
        for strategy_index, strategy_key in enumerate(strategy_keys):
            estimates = np.array([evaluation[p][strategy_key]["bootstrap"]["eer"]["estimate"] for p in pool_names])
            lower_bounds = np.array([evaluation[p][strategy_key]["bootstrap"]["eer"]["ci_lower"] for p in pool_names])
            upper_bounds = np.array([evaluation[p][strategy_key]["bootstrap"]["eer"]["ci_upper"] for p in pool_names])
            yerr = np.vstack([np.clip(estimates - lower_bounds, 0, None),
                              np.clip(upper_bounds - estimates, 0, None)])
            bar_offsets = x_positions + (strategy_index - (n_strategies - 1) / 2) * bar_width
            bars = ax.bar(bar_offsets, estimates, width=bar_width, yerr=yerr, capsize=4,
                          color=colormap(strategy_index), alpha=0.85,
                          label=SCORE_STRATEGY_LABELS[strategy_key])
            for bar, value in zip(bars, estimates):
                ax.text(bar.get_x() + bar.get_width() / 2, value, f"{value:.2%}",
                        ha="center", va="bottom", fontsize=7, fontweight="bold")
        ax.set_xticks(x_positions)
        ax.set_xticklabels(pool_names)
        ax.set_ylabel("Audio-level EER")
        ax.set_title(f"EER per Score Strategy — {distance_metric}\n(error bars: bootstrap CI)", fontweight="bold")
        ax.legend(fontsize=8)
        ax.grid(True, axis="y", alpha=0.3)

        # Panels 1..N: ROC per evaluation pool
        for pool_index, pool_name in enumerate(pool_names, start=1):
            ax = axes[pool_index]
            for strategy_index, strategy_key in enumerate(strategy_keys):
                strategy_result = evaluation[pool_name][strategy_key]
                false_positive_rate, true_positive_rate, _ = roc_curve(
                    strategy_result["labels"], -np.asarray(strategy_result["scores"]), pos_label=1
                )
                roc_auc = auc(false_positive_rate, true_positive_rate)
                ax.plot(false_positive_rate, true_positive_rate, linewidth=2, color=colormap(strategy_index),
                        label=f"{SCORE_STRATEGY_LABELS[strategy_key]} (AUC = {roc_auc:.4f})")
            ax.plot([0, 1], [0, 1], color="gray", linestyle=":", linewidth=1, label="Chance level")
            ax.set_xlabel("False Positive Rate")
            ax.set_ylabel("True Positive Rate")
            ax.set_title(f"ROC — {pool_name} ({distance_metric})", fontweight="bold")
            ax.legend(fontsize=7, loc="lower right")
            ax.grid(True, alpha=0.3)

        plt.tight_layout()
        output_file_path = path_template.format(distance_metric=distance_metric)
        plt.savefig(output_file_path, dpi=dpi, bbox_inches="tight")
        plt.show()
        print(f"Strategy EER/ROC comparison saved to {output_file_path}")
        saved_paths[distance_metric] = output_file_path

    return saved_paths


strategy_eer_summary = build_strategy_eer_summary_table(strategy_eer_results)
