###########################################
"""Cross-Corpus Domain-Shift Diagnostic — Score Distribution vs Frozen Threshold"""
###########################################

def plot_cross_corpus_domain_shift(audio_results, frozen_threshold, distance_metric,
                                    output_path, run_name, dpi=FIGURE_DPI):
    """
    Visual diagnostic for a cross-corpus (unseen-device) evaluation:
    overlays the genuine/spliced audio-level score distributions against
    the in-domain frozen threshold, making explicit why a fixed threshold
    calibrated on the training corpus may fail to transfer under domain
    shift, independent of whether splicing was correctly generated.
    """
    scores = audio_results['scores']
    labels = audio_results['labels']

    fig, ax = plt.subplots(figsize=(8, 6))
    ax.hist(scores[labels == 1], bins=20, alpha=0.6, color='steelblue', label='Genuine (unseen corpus)')
    ax.hist(scores[labels == 0], bins=20, alpha=0.6, color='darkorange', label='Spliced (unseen corpus)')
    ax.axvline(x=frozen_threshold, color='red', linestyle='--', linewidth=1.5,
               label=f'Frozen threshold (in-domain) = {frozen_threshold:.4f}')
    ax.set_title(f'Cross-Corpus Domain Shift — {distance_metric}\n'
                 f'Self-calibrated reference EER on this corpus: {audio_results["eer"]:.4%}',
                 fontweight='bold')
    ax.set_xlabel('Audio-level max distance')
    ax.set_ylabel('Count')
    ax.legend(fontsize=9)
    ax.grid(True, alpha=0.3)
    plt.tight_layout()

    output_file_path = os.path.join(output_path, f"domain_shift_{distance_metric}_{run_name}.png")
    plt.savefig(output_file_path, dpi=dpi, bbox_inches='tight')
    plt.show()
    print(f"Domain-shift diagnostic saved to {output_file_path}")

