def plot_detection_roc_comparison(results_by_metric, level, title, output_file_path, dpi=FIGURE_DPI):
    """
    ROC at a given detection level ('window' or 'audio'). Label convention
    in eer_evaluation.py: label = 1 genuine, label = 0 impostor/spliced,
    with distances INVERTED internally by calculate_eer(); roc_curve here
    is computed the same way (pos_label=1 on the inverted score) so AUC/EER
    match calculate_eer()'s own reporting.
    """
    fig, ax = plt.subplots(figsize=(8, 7))

    for distance_metric, full_result in results_by_metric.items():
        level_result = full_result[level]
        scores_inverted = -np.asarray(level_result['scores'])  # same inversion as calculate_eer()
        labels = level_result['labels']

        false_positive_rate, true_positive_rate, _ = roc_curve(labels, scores_inverted, pos_label=1)
        roc_auc = auc(false_positive_rate, true_positive_rate)
        ax.plot(false_positive_rate, true_positive_rate, linewidth=2,
                label=f"{distance_metric.capitalize()}  (AUC = {roc_auc:.4f}, EER = {level_result['eer']:.4%})")

    ax.plot([0, 1], [0, 1], color='gray', linestyle=':', linewidth=1, label='Chance level')
    ax.set_xlabel('False Positive Rate')
    ax.set_ylabel('True Positive Rate')
    ax.set_title(title, fontweight='bold')
    ax.legend(fontsize=9, loc='lower right')
    ax.grid(True, alpha=0.3)
    plt.tight_layout()

    plt.savefig(output_file_path, dpi=dpi, bbox_inches='tight')
    plt.show()
    print(f"ROC curve comparison saved to {output_file_path}")


