def plot_roc_curve_comparison(results_by_metric, title, output_file_path, dpi=FIGURE_DPI):
    """
    Overlays the ROC curve of each distance metric on a single axis, using
    the raw score/label population stored in each cached discriminability
    result (label convention: 0 = genuine pair, 1 = impostor pair, matching
    compute_eer_from_scores()).
    """
    fig, ax = plt.subplots(figsize=(8, 7))

    for distance_metric, result in results_by_metric.items():
        false_positive_rate, true_positive_rate, _ = roc_curve(
            result["labels"], result["scores"], pos_label=1
        )
        roc_auc = auc(false_positive_rate, true_positive_rate)
        ax.plot(false_positive_rate, true_positive_rate, linewidth=2,
                label=f"{distance_metric.capitalize()}  (AUC = {roc_auc:.4f}, EER = {result['eer']:.4%})")

    ax.plot([0, 1], [0, 1], color='gray', linestyle=':', linewidth=1, label='Chance level')
    ax.set_xlabel('False Positive Rate')
    ax.set_ylabel('True Positive Rate')
    ax.set_title(title, fontweight='bold')
    ax.legend(fontsize=9, loc='lower right')
    ax.grid(True, alpha=0.3)
    plt.tight_layout()

    plt.savefig(output_file_path, dpi=dpi, bbox_inches='tight')
    plt.show()
    print(f"ROC curve comparison saved to {output_file_path}")


