def collect_raw_consecutive_distances(audio_pool, n_audios, distance_metric="euclidean", VI=None):
    """Concatenates the raw consecutive-window distances of `n_audios` randomly sampled audios."""
    sampled_audios = random.sample(audio_pool, min(n_audios, len(audio_pool)))
    distance_arrays = []
    for audio_info in sampled_audios:
        distances, _ = _extract_consecutive_distances(
            audio_info['audio'], model, device, sr=SR, win_sec=WIN_LENGTH_SEC, hop_sec=HOP_LENGTH_SEC_EVAL,
            n_fft=N_FFT, hop_length_fft=HOP_LENGTH_FFT, distance_metric=distance_metric, VI=VI
        )
        if len(distances) > 0:
            distance_arrays.append(distances)
    return np.concatenate(distance_arrays)


set_all_seeds(RANDOM_SEED)
diagnostic_pools = {"val (in-domain)": val_audios, "unseen devices": unseen_devices_dataset}

for pool_name, audio_pool in diagnostic_pools.items():
    pool_distances = collect_raw_consecutive_distances(audio_pool, DISTANCE_DIAGNOSTIC_N_AUDIOS)
    percentile_values = np.percentile(pool_distances, DISTANCE_DIAGNOSTIC_PERCENTILES)
    percentile_report = " | ".join(f"p{p} = {v:.6f}" for p, v in zip(DISTANCE_DIAGNOSTIC_PERCENTILES, percentile_values))
    print(f"[{pool_name}] consecutive distances (n={len(pool_distances)}): {percentile_report}")

