def collect_pool_embeddings(audio_pool, n_windows, model, device,
                            sr=SR, win_sec=WIN_LENGTH_SEC, n_fft=N_FFT, hop_length_fft=HOP_LENGTH_FFT):
    """Embeds `n_windows` random windows (one per randomly drawn audio) and returns (embeddings, device_names)."""
    win_len = int(win_sec * sr)
    features, device_names = [], []
    for audio_info in random.choices(audio_pool, k=n_windows):
        signal = audio_info['audio']
        start = random.randint(0, max(len(signal) - win_len, 0))
        feature = extract_stft_power_spectrogram_db(signal[start:start + win_len], sr=sr, n_fft=n_fft,
                                                    hop_length=hop_length_fft, freq_mask=TRAIN_FREQUENCY_MASK)
        features.append((feature - np.mean(feature)) / (np.std(feature) + 1e-8))
        device_names.append(audio_info['device'])

    model.eval()
    specs = torch.tensor(np.array(features), dtype=torch.float32).unsqueeze(1).to(device)
    with torch.no_grad():
        embeddings = model(specs).cpu()
    return embeddings, np.array(device_names)


set_all_seeds(RANDOM_SEED)
for pool_name, audio_pool in {"val (in-domain)": val_audios, "unseen devices": unseen_devices_dataset}.items():
    pool_embeddings, pool_device_names = collect_pool_embeddings(
        audio_pool, EMBEDDING_DIAGNOSTIC_N_WINDOWS, model, device)

    pairwise_distances = torch.cdist(pool_embeddings, pool_embeddings)
    same_device_mask = torch.tensor(pool_device_names[:, None] == pool_device_names[None, :])
    off_diagonal_mask = ~torch.eye(len(pool_embeddings), dtype=torch.bool)

    intra_device = pairwise_distances[same_device_mask & off_diagonal_mask]
    inter_device = pairwise_distances[~same_device_mask]

    print(f"[{pool_name}]")
    print(f"   Mean per-dimension std:   {pool_embeddings.std(dim=0).mean().item():.6f}  "
          f"(isotropic reference: {1.0 / np.sqrt(OUT_DIM):.6f})")
    print(f"   Mean L2 norm:             {pool_embeddings.norm(dim=1).mean().item():.6f}")
    print(f"   Intra-device distance:    mean = {intra_device.mean().item():.6f}")
    print(f"   Inter-device distance:    mean = {inter_device.mean().item():.6f}")

