def mean_log_power_spectrum(audio_pool, n_audios, sr=SR, win_sec=WIN_LENGTH_SEC):
    """Mean per-bin log-power spectrum (dB, BEFORE window normalization) over one random window per audio."""
    win_len = int(win_sec * sr)
    spectra = []
    for audio_info in random.sample(audio_pool, min(n_audios, len(audio_pool))):
        signal = audio_info['audio']
        start = random.randint(0, max(len(signal) - win_len, 0))
        feature = extract_stft_power_spectrogram_db(signal[start:start + win_len], sr=sr)
        spectra.append(feature.mean(axis=1))
    return np.mean(spectra, axis=0)


