def lowpass_pool(audio_pool, cutoff_hz=LOWPASS_TEST_CUTOFF_HZ, order=LOWPASS_TEST_ORDER, sr=SR):
    sos = butter(order, cutoff_hz, btype="low", fs=sr, output="sos")
    return [{**a, "audio": sosfiltfilt(sos, a["audio"]).astype(a["audio"].dtype)} for a in audio_pool]

