def audit_window_level_splice_points(audio_pool, top_db=TOP_DB, sr=SR):

    device_names = sorted({item['device'] for item in audio_pool})
    audios_by_device = {
        device_name: [item for item in audio_pool if item['device'] == device_name]
        for device_name in device_names
    }

    n_splices = 0
    n_without_destination_content = 0
    overshoot_s = []

    for source_device, destination_device in permutations(device_names, 2):
        source_item = random.choice(audios_by_device[source_device])
        destination_item = random.choice(audios_by_device[destination_device])

        spliced_audio, cut_sample = generate_simple_splicing(
            source_item['audio'], destination_item['audio'], top_db=top_db
        )
        if spliced_audio is None:
            continue

        n_splices += 1
        destination_length = len(destination_item['audio'])
        if cut_sample >= destination_length:
            n_without_destination_content += 1
            overshoot_s.append((cut_sample - destination_length) / sr)

    fraction = n_without_destination_content / max(n_splices, 1)
    mean_overshoot_s = float(np.mean(overshoot_s)) if overshoot_s else None

    print(f"Splices generated: {n_splices} | "
          f"without destination content: {n_without_destination_content} ({fraction:.1%})")
    if mean_overshoot_s is not None:
        print(f"Mean overshoot of the cut beyond the end of the destination: "
              f"{mean_overshoot_s:.2f} s")

    return {
        "n_splices": n_splices,
        "n_without_destination_content": n_without_destination_content,
        "fraction": fraction,
        "mean_overshoot_s": mean_overshoot_s,
    }


