def build_duration_records(audio_pools):
    """
    Builds one record per audio item (device x condition x speaker file)
    with its duration in seconds, computed from the in-memory signal.
    """
    records = []
    for split_name, audio_items in audio_pools.items():
        for audio_info in audio_items:
            records.append({
                "split": split_name,
                "condition": audio_info["condition"],
                "speaker": audio_info["filename"],
                "device": audio_info["device"],
                "duration_sec": len(audio_info["audio"]) / audio_info["sr"],
            })
    return pd.DataFrame.from_records(records)


def audit_speaker_durations(duration_records,
                            tolerance_sec=SPEAKER_DURATION_TOLERANCE_SEC,
                            exact_decimals=DURATION_EXACT_DECIMALS,
                            decimals=SPEAKER_DURATION_DECIMALS):
    """
    One row per (condition, speaker) take, aggregated over ALL devices:
    duration, cross-device spread, number of distinct durations and a
    same-duration flag.
    """
    audit = (
        duration_records
        .assign(duration_exact=duration_records["duration_sec"].round(exact_decimals))
        .groupby(["condition", "speaker"])
        .agg(split=("split", "first"),
             n_devices=("device", "nunique"),
             duration_sec=("duration_sec", "median"),
             min_duration_sec=("duration_sec", "min"),
             max_duration_sec=("duration_sec", "max"),
             n_distinct_durations=("duration_exact", "nunique"))
        .reset_index()
    )
    audit["spread_sec"] = audit["max_duration_sec"] - audit["min_duration_sec"]
    audit["same_duration_across_devices"] = audit["spread_sec"] <= tolerance_sec
    return audit.round(decimals)
