def _device_lag_samples(device_name, take_key):
    if device_name == LAG_REFERENCE_DEVICE:
        return 0
    return DEVICE_LAG_LOOKUP[(take_key[0], take_key[1], device_name)]
def estimate_lag_start_end(reference_signal, target_signal, segment_sec, max_lag_samples, sr=SR):
    segment_len = round(segment_sec * sr)
    lag_start = estimate_lag_samples(reference_signal[:segment_len], target_signal[:segment_len], max_lag_samples)
    lag_end = estimate_lag_samples(reference_signal[-segment_len:], target_signal[-segment_len:], max_lag_samples)
    return lag_start, lag_end

# Example on the worst case
