def bootstrap_ci(statistic_fn, *arrays, strata=None, n_resamples=1000,
                 confidence_level=0.95, seed=42):
    """Percentile bootstrap over the first axis; stratified resampling if `strata` is given."""
    arrays = [np.asarray(a) for a in arrays]
    rng = np.random.default_rng(seed)
    if strata is not None:
        strata = np.asarray(strata)
        stratum_indices = [np.flatnonzero(strata == s) for s in np.unique(strata)]
        draw = lambda: np.concatenate([rng.choice(idx, len(idx), replace=True) for idx in stratum_indices])
    else:
        draw = lambda: rng.integers(0, len(arrays[0]), len(arrays[0]))
    replicates = np.array([statistic_fn(*[a[idx] for a in arrays])
                           for idx in (draw() for _ in range(n_resamples))])
    tail = (1 - confidence_level) / 2
    lower, upper = np.nanpercentile(replicates, [100 * tail, 100 * (1 - tail)])
    return float(statistic_fn(*arrays)), float(lower), float(upper)

def load_eer_detail(name):
    with open(os.path.join(output_path, f"eer_detail_{name}.pkl"), "rb") as f:
        return pickle.load(f)

