for source_name, records in record_sources.items():
    for strategy_key in LOCALIZATION_STRATEGY_KEYS:
        errors = np.array([r[f"{strategy_key}_localization_error_s"] for r in records
                           if f"{strategy_key}_localization_error_s" in r])
        if len(errors):
            median, lower, upper = bootstrap_ci(np.median, errors)
            print(f"[{source_name}] {strategy_key}: median {median:.3f} s "
                  f"[{lower:.3f}, {upper:.3f}] | mean {errors.mean():.3f} s")

