# Standalone cell: balanced window-level evaluation (Euclidean only) for
# TEST, UNSEEN DEVICES and AI SPLICES. Reads only the pickles saved on Drive.

import os
import pickle
import numpy as np
from sklearn.metrics import roc_curve
from google.colab import drive

drive.mount('/content/drive')

output_path = "/content/drive/MyDrive/AudioAuthentication_results_nfft2048_NV_3_FullSpectrum"
run_name = "euclidean_uv_epochs840_val15_win1_cosface_outdim64"
eval_run_name = f"{run_name}_40_nm_medf3_entw10"

N_REPEATS = 1000
SEED = 42

# label -> pickle file name (each holds a dict with a 'window' entry)
sources = {
    "Test":           f"eer_detail_{eval_run_name}.pkl",
    "Unseen devices": f"eer_detail_unseen_devices_{eval_run_name}.pkl",
    "AI splices":     f"ia_splicing_detail_{eval_run_name}.pkl",
}


def eer_from_scores(s, l):
    """Same logic as calculate_eer(): distances inverted so genuine = positive class."""
    fpr, tpr, _ = roc_curve(l, -s, pos_label=1)
    fnr = 1.0 - tpr
    idx = np.argmin(np.abs(fpr - fnr))
    return float((fpr[idx] + fnr[idx]) / 2)


def far_frr(s, l, thr):
    """FAR: impostors not flagged. FRR: genuine wrongly flagged (flag = score > thr)."""
    flagged = s > thr
    return float((~flagged[l == 0]).mean()), float(flagged[l == 1].mean())


def precision(tpr, fpr, prevalence):
    denominator = tpr * prevalence + fpr * (1 - prevalence)
    return float(tpr * prevalence / denominator) if denominator > 0 else float("nan")


def mean_std_ci(values):
    values = np.asarray(values)
    lo, hi = np.percentile(values, [2.5, 97.5])
    return values.mean(), values.std(), lo, hi


summary_rows = []

for set_name, file_name in sources.items():
    file_path = os.path.join(output_path, file_name)
    if not os.path.exists(file_path):
        print(f"NOT FOUND: {file_path}")
        continue
    with open(file_path, "rb") as f:
        window = pickle.load(f)["window"]

    scores = np.asarray(window["scores"], dtype=np.float64)
    labels = np.asarray(window["labels"])           # 1 = genuine, 0 = impostor
    frozen_threshold = float(window["optimal_threshold"])

    genuine_idx = np.flatnonzero(labels == 1)
    impostor_idx = np.flatnonzero(labels == 0)
    n_impostors = len(impostor_idx)

    full_eer = eer_from_scores(scores, labels)
    full_far, full_frr = far_frr(scores, labels, frozen_threshold)

    rng = np.random.default_rng(SEED)
    eers, fars, frrs = [], [], []
    for _ in range(N_REPEATS):
        chosen_genuine = rng.choice(genuine_idx, size=n_impostors, replace=False)
        idx = np.concatenate([chosen_genuine, impostor_idx])
        eers.append(eer_from_scores(scores[idx], labels[idx]))
        far, frr = far_frr(scores[idx], labels[idx], frozen_threshold)
        fars.append(far)
        frrs.append(frr)

    # Precision of the 'splice' alarm (positive = impostor/spliced): TPR = 1 - FAR, FPR = FRR
    tpr, fpr = 1.0 - full_far, full_frr
    prevalence_real = n_impostors / len(labels)

    print(f"\n=== {set_name} ===")
    print(f"Genuine={len(genuine_idx):,} | Impostor={n_impostors:,} | frozen window threshold={frozen_threshold:.4f}")
    for name, full_value, values in [("EER", full_eer, eers), ("FAR", full_far, fars), ("FRR", full_frr, frrs)]:
        m, s, lo, hi = mean_std_ci(values)
        print(f"{name}: full set {full_value:.2%} | balanced {m:.2%} ± {s:.2%} [{lo:.2%}, {hi:.2%}]")
    print(f"Precision at real prevalence ({prevalence_real:.2%}): {precision(tpr, fpr, prevalence_real):.2%}")
    print(f"Precision at 50% prevalence:                  {precision(tpr, fpr, 0.5):.2%}")

    summary_rows.append((set_name, n_impostors, full_eer, mean_std_ci(eers),
                         full_far, mean_std_ci(fars), full_frr, mean_std_ci(frrs),
                         precision(tpr, fpr, prevalence_real), precision(tpr, fpr, 0.5)))


print("| Set | Impostor pairs | EER (full) | EER (balanced) | FAR (full) | FAR (balanced) | FRR (full) | FRR (balanced) | Precision (real prev.) | Precision (50 %) |")
print("|---|---|---|---|---|---|---|---|---|---|")
for (name, n_imp, e_full, e_bal, a_full, a_bal, r_full, r_bal, p_real, p_half) in summary_rows:
    fmt = lambda t: f"{t[0]:.2%} ± {t[1]:.2%}"
    print(f"| {name} | {n_imp:,} | {e_full:.2%} | {fmt(e_bal)} | {a_full:.2%} | {fmt(a_bal)} | "
          f"{r_full:.2%} | {fmt(r_bal)} | {p_real:.2%} | {p_half:.2%} |")

# Standalone cell: balanced WINDOW-level evaluation for the 4 distance metrics
# on TEST, UNSEEN DEVICES and AI SPLICES. Reads only pickles saved on Drive.

import os
import pickle
import numpy as np
from sklearn.metrics import roc_curve
from google.colab import drive
import csv
drive.mount('/content/drive')

output_path = "/content/drive/MyDrive/AudioAuthentication_results_nfft2048_NV_3_FullSpectrum"
run_name = "euclidean_uv_epochs840_val15_win1_cosface_outdim64"
eval_run_name = f"{run_name}_40_nm_medf3_entw10"

N_REPEATS = 1000
SEED = 42
METRICS = ["euclidean", "mahalanobis", "manhattan", "snr"]


def metric_tag(metric):
    return "" if metric == "euclidean" else f"{metric}_"


# (set name, metric) -> pickle file name, following the names used when saving
def pickle_name(set_name, metric):
    if set_name == "Test":
        return f"eer_detail_{eval_run_name}.pkl" if metric == "euclidean" \
            else f"eer_detail_final_test_{metric}_{eval_run_name}.pkl"
    if set_name == "Unseen devices":
        return f"eer_detail_unseen_devices_{metric_tag(metric)}{eval_run_name}.pkl"
    if set_name == "AI splices":
        return f"ia_splicing_detail_{metric_tag(metric)}{eval_run_name}.pkl"


def eer_from_scores(s, l):
    fpr, tpr, _ = roc_curve(l, -s, pos_label=1)
    fnr = 1.0 - tpr
    idx = np.argmin(np.abs(fpr - fnr))
    return float((fpr[idx] + fnr[idx]) / 2)


def far_frr(s, l, thr):
    flagged = s > thr
    return float((~flagged[l == 0]).mean()), float(flagged[l == 1].mean())


def precision(tpr, fpr, prevalence):
    denominator = tpr * prevalence + fpr * (1 - prevalence)
    return float(tpr * prevalence / denominator) if denominator > 0 else float("nan")


def pct(x):
    return "n.d." if np.isnan(x) else f"{x:.2%}"


rows = []
for set_name in ["Test", "Unseen devices", "AI splices"]:
    for metric in METRICS:
        file_path = os.path.join(output_path, pickle_name(set_name, metric))
        if not os.path.exists(file_path):
            print(f"NOT FOUND: {file_path}")
            continue
        with open(file_path, "rb") as f:
            window = pickle.load(f)["window"]

        scores = np.asarray(window["scores"], dtype=np.float64)
        labels = np.asarray(window["labels"])           # 1 = genuine, 0 = impostor
        threshold = float(window["optimal_threshold"])

        finite = np.isfinite(scores)                    # SNR can return inf
        if not finite.all():
            print(f"[{set_name} | {metric}] dropping {(~finite).sum()} non-finite scores")
            scores, labels = scores[finite], labels[finite]

        genuine_idx = np.flatnonzero(labels == 1)
        impostor_idx = np.flatnonzero(labels == 0)
        n_imp = len(impostor_idx)

        # Full (imbalanced) set
        full_eer = eer_from_scores(scores, labels)
        full_far, full_frr = far_frr(scores, labels, threshold)

        # Balanced: all impostors + n_imp genuine pairs drawn without replacement
        rng = np.random.default_rng(SEED)
        eers, fars, frrs = [], [], []
        for _ in range(N_REPEATS):
            idx = np.concatenate([rng.choice(genuine_idx, size=n_imp, replace=False), impostor_idx])
            eers.append(eer_from_scores(scores[idx], labels[idx]))
            far_b, frr_b = far_frr(scores[idx], labels[idx], threshold)
            fars.append(far_b)
            frrs.append(frr_b)

        rows.append(dict(
            set=set_name, metric=metric, n_gen_full=len(genuine_idx), n_per_class_bal=n_imp, thr=threshold,
            eer_full=full_eer, eer_bal=np.mean(eers), eer_std=np.std(eers),
            far_full=full_far, far_bal=np.mean(fars), far_std=np.std(fars),
            frr_full=full_frr, frr_bal=np.mean(frrs), frr_std=np.std(frrs),
        ))

# Plain-text table
header = (f"{'Set':<15}{'Metric':<13}{'Gen.(full)':>11}{'N/class(bal)':>13}{'Thr.':>8}"
          f"{'EER full':>10}{'EER bal.':>10}"
          f"{'FAR full':>10}{'FAR bal.':>10}"
          f"{'FRR full':>10}{'FRR bal.':>10}")
print("\nWINDOW-level evaluation: full vs. balanced\n")
print(header)
print("-" * len(header))
previous_set = None
for r in rows:
    if previous_set is not None and r['set'] != previous_set:
        print()
    previous_set = r['set']
    print(f"{r['set']:<15}{r['metric']:<13}{r['n_gen_full']:>11,}{r['n_per_class_bal']:>13,}{r['thr']:>8.4f}"
          f"{r['eer_full']:>10.2%}{r['eer_bal']:>10.2%}"
          f"{r['far_full']:>10.2%}{r['far_bal']:>10.2%}"
          f"{r['frr_full']:>10.2%}{r['frr_bal']:>10.2%}")

# CSV export (includes the standard deviations)
csv_path = os.path.join(output_path, f"window_balanced_evaluation_{eval_run_name}.csv")
with open(csv_path, "w", newline="", encoding="utf-8") as f:
    writer = csv.DictWriter(f, fieldnames=list(rows[0].keys()))
    writer.writeheader()
    writer.writerows(rows)
print(f"\nCSV saved to {csv_path}")

# Standalone cell: AUDIO-level EER plots (score histogram + DET curve) for the 4 metrics,
# on AI splices, Test and Unseen devices. Reads only pickles saved on Drive.

import os, pickle
import numpy as np
import matplotlib.pyplot as plt
from sklearn.metrics import roc_curve
from google.colab import drive

drive.mount('/content/drive')

output_path = "/content/drive/MyDrive/AudioAuthentication_results_nfft2048_NV_3_FullSpectrum"
run_name = "euclidean_uv_epochs840_val15_win1_cosface_outdim64"
eval_run_name = f"{run_name}_40_nm_medf3_entw10"
METRICS = ["euclidean", "mahalanobis", "manhattan", "snr"]
DPI = 400


def tag(metric):
    return "" if metric == "euclidean" else f"{metric}_"


# set name -> (file name builder, key holding the audio-level EER population)
SETS = {
    "AI splices": (lambda m: f"ia_splicing_detail_{tag(m)}{eval_run_name}.pkl", "audio_eer"),
    "Test": (lambda m: f"eer_detail_{eval_run_name}.pkl" if m == "euclidean"
             else f"eer_detail_final_test_{m}_{eval_run_name}.pkl", "audio"),
    "Unseen devices": (lambda m: f"eer_detail_unseen_devices_{tag(m)}{eval_run_name}.pkl", "audio"),
}


def det_points(scores, labels):
    """FAR (impostor accepted) vs FRR (genuine rejected); label 1 = authentic, 0 = spliced."""
    fpr, tpr, _ = roc_curve(labels, -scores, pos_label=1)
    return fpr * 100, (1 - tpr) * 100


for set_name, (name_fn, key) in SETS.items():
    fig, axes = plt.subplots(2, len(METRICS), figsize=(5 * len(METRICS), 9))
    for col, metric in enumerate(METRICS):
        path = os.path.join(output_path, name_fn(metric))
        if not os.path.exists(path):
            print(f"NOT FOUND: {path}")
            axes[0, col].axis("off"); axes[1, col].axis("off")
            continue
        with open(path, "rb") as f:
            res = pickle.load(f)[key]
        scores = np.asarray(res["scores"], dtype=np.float64)
        labels = np.asarray(res["labels"])
        finite = np.isfinite(scores)
        scores, labels = scores[finite], labels[finite]
        thr = res["optimal_threshold"]
        n_auth, n_spl = int((labels == 1).sum()), int((labels == 0).sum())

        ax = axes[0, col]
        bins = np.linspace(scores.min(), scores.max(), 30)
        ax.hist(scores[labels == 1], bins=bins, alpha=0.6, color="steelblue", density=True,
                label=f"Authentic (n={n_auth})")
        ax.hist(scores[labels == 0], bins=bins, alpha=0.6, color="tomato", density=True,
                label=f"Spliced (n={n_spl})")
        ax.axvline(thr, color="black", linestyle="--", label=f"Frozen threshold = {thr:.3f}")
        ax.set_title(f"{metric.capitalize()}\nEER = {res['eer']:.2%}", fontweight="bold")
        ax.set_xlabel("Audio score (max consecutive distance)")
        ax.set_ylabel("Density")
        ax.legend(fontsize=8); ax.grid(alpha=0.3)

        ax = axes[1, col]
        far, frr = det_points(scores, labels)
        ax.plot(far, frr, color="steelblue", linewidth=2, label="DET curve")
        ax.plot([0, 100], [100, 0], "k--", alpha=0.4, linewidth=1)
        ax.scatter([res["eer"] * 100], [res["eer"] * 100], color="red", s=70, zorder=5,
                   label=f"EER = {res['eer']:.2%}")
        ax.set_xlabel("FAR (%)"); ax.set_ylabel("FRR (%)")
        ax.set_xlim(0, 100); ax.set_ylim(0, 100)
        ax.legend(fontsize=8); ax.grid(alpha=0.3)

    fig.suptitle(f"AUDIO-level EER: {set_name}", fontsize=14, fontweight="bold")
    plt.tight_layout(rect=[0, 0, 1, 0.96])
    out = os.path.join(output_path, f"audio_level_eer_{set_name.replace(' ', '_').lower()}_{eval_run_name}.png")
    plt.savefig(out, dpi=DPI, bbox_inches="tight")
    plt.show()
    print(f"Saved: {out}")

import numpy as np, pickle, os
