import os, sys, pickle, csv
import numpy as np
from google.colab import drive

drive.mount('/content/drive')
sys.path.append('/content/drive/MyDrive/AudioAuthentication')
from eer_evaluation import calculate_eer, calculate_far_frr_at_threshold

output_path = "/content/drive/MyDrive/AudioAuthentication_results_nfft2048_NV_3_FullSpectrum"
run_name = "euclidean_uv_epochs840_val15_win1_cosface_outdim64"
eval_run_name = f"{run_name}_40_nm_medf3_entw10"

DISTANCE_METRICS = ["euclidean", "mahalanobis", "manhattan", "snr"]
DETECTION_LEVELS = ("audio", "window")


def metric_tag(metric):
    return "" if metric == "euclidean" else f"{metric}_"


# evaluation set -> (pickle-name builder, key of the audio-level population)
EVALUATION_SETS = {
    "Test": (
        lambda m: f"eer_detail_{eval_run_name}.pkl" if m == "euclidean"
        else f"eer_detail_final_test_{m}_{eval_run_name}.pkl",
        "audio",
    ),
    "Unseen devices": (
        lambda m: f"eer_detail_unseen_devices_{metric_tag(m)}{eval_run_name}.pkl",
        "audio",
    ),
    "AI splices": (
        lambda m: f"ia_splicing_detail_{metric_tag(m)}{eval_run_name}.pkl",
        "audio_eer",
    ),
}

records = []
for set_name, (file_name_fn, audio_key) in EVALUATION_SETS.items():
    for metric in DISTANCE_METRICS:
        file_path = os.path.join(output_path, file_name_fn(metric))
        if not os.path.exists(file_path):
            print(f"NOT FOUND: {file_path}")
            continue
        with open(file_path, "rb") as f:
            detail = pickle.load(f)

        for level in DETECTION_LEVELS:
            result = detail[audio_key if level == "audio" else "window"]
            scores = np.asarray(result["scores"], dtype=np.float64)
            labels = np.asarray(result["labels"])
            finite = np.isfinite(scores)              # SNR can return inf
            scores, labels = scores[finite], labels[finite]

            frozen_threshold = float(result["optimal_threshold"])
            eer_sc, self_calibrated_threshold = calculate_eer(scores, labels)
            far_frozen, frr_frozen = calculate_far_frr_at_threshold(scores, labels, frozen_threshold)
            far_sc, frr_sc = calculate_far_frr_at_threshold(scores, labels, self_calibrated_threshold)

            # Error rate at the frozen operating point: (FAR + FRR) / 2 (HTER)
            eer_frozen = (far_frozen + frr_frozen) / 2.0

            records.append(dict(
                set=set_name, metric=metric, level=level,
                n_genuine=int((labels == 1).sum()), n_impostor=int((labels == 0).sum()),
                thr_frozen=frozen_threshold, far_frozen=far_frozen, frr_frozen=frr_frozen,
                thr_self=float(self_calibrated_threshold), far_self=far_sc, frr_self=frr_sc,
                eer_frozen=float(eer_frozen), eer_self=float(eer_sc),
            ))

