# Standalone cell: audio-level detection table with 95% bootstrap CIs for
# FAR, FRR, mean error and self-calibrated EER (all evaluation sets, including
# clean-only and noise-only). Reads only the pickles saved on Drive.

import os, sys, pickle
import numpy as np
import pandas as pd
from google.colab import drive

drive.mount('/content/drive')
sys.path.append('/content/drive/MyDrive/AudioAuthentication')
from eer_evaluation import calculate_eer, calculate_far_frr_at_threshold

# ── Configuration (must match the original run) ──────────────────────────────
output_path = "/content/drive/MyDrive/AudioAuthentication_results_nfft2048_NV_3_FullSpectrum"
run_name = "euclidean_uv_epochs840_val15_win1_cosface_outdim64"
eval_run_name = f"{run_name}_40_nm_medf3_entw10"

N_RESAMPLES = 1000
CONFIDENCE = 0.95
SEED = 42
DECIMALS = 2


# ── Helpers ──────────────────────────────────────────────────────────────────
def load_pickle(file_name):
    path = os.path.join(output_path, file_name)
    if not os.path.exists(path):
        print(f"NOT FOUND: {path}")
        return None
    with open(path, "rb") as f:
        return pickle.load(f)


def bootstrap_detection_table_row(scores, labels, frozen_threshold,
                                  n_resamples=N_RESAMPLES, confidence=CONFIDENCE, seed=SEED):
    """
    Stratified percentile bootstrap (resampling audios within each class).
    FAR / FRR / mean error use the FROZEN threshold (never re-estimated);
    EER is re-estimated per replicate (it defines its own threshold).
    Label convention: 1 = authentic, 0 = spliced.
    Returns {metric: (estimate, ci_low, ci_high)} in percent.
    """
    rng = np.random.default_rng(seed)
    strata = [np.flatnonzero(labels == c) for c in np.unique(labels)]

    def _metrics(s, l):
        far, frr = calculate_far_frr_at_threshold(s, l, frozen_threshold)
        return {"far": far, "frr": frr, "mean_err": (far + frr) / 2,
                "eer": calculate_eer(s, l)[0]}

    point = _metrics(scores, labels)
    replicates = {k: np.empty(n_resamples) for k in point}
    for i in range(n_resamples):
        idx = np.concatenate([rng.choice(s, size=len(s), replace=True) for s in strata])
        for k, v in _metrics(scores[idx], labels[idx]).items():
            replicates[k][i] = v

    tail = (1 - confidence) / 2
    out = {}
    for k in point:
        lo, hi = np.nanpercentile(replicates[k], [100 * tail, 100 * (1 - tail)])
        out[k] = (100 * point[k], 100 * lo, 100 * hi)
    return out


def summarize_audio_level(result):
    scores = np.asarray(result["scores"], dtype=np.float64)
    labels = np.asarray(result["labels"])
    finite = np.isfinite(scores)
    scores, labels = scores[finite], labels[finite]
    tau = float(result["optimal_threshold"])
    return {
        "n_auth": int((labels == 1).sum()),
        "n_spliced": int((labels == 0).sum()),
        "tau": tau,
        "ci": bootstrap_detection_table_row(scores, labels, tau),
    }


def fmt(triple, d=DECIMALS):
    est, lo, hi = triple
    return f"{est:.{d}f} [{lo:.{d}f}, {hi:.{d}f}]"


# ── Load each evaluation set ─────────────────────────────────────────────────
experiment = load_pickle(f"experiment_{eval_run_name}.pkl")
test_detail = load_pickle(f"eer_detail_{eval_run_name}.pkl")
unseen_detail = load_pickle(f"eer_detail_unseen_devices_{eval_run_name}.pkl")
ia_detail = load_pickle(f"ia_splicing_detail_{eval_run_name}.pkl")

audio_level_sources = {
    "Test (seen devices)": test_detail["audio"] if test_detail else None,
    "Test, clean only": experiment["clean_results"]["audio"] if experiment else None,
    "Test, noise only": experiment["noise_results"]["audio"] if experiment else None,
    "Unseen devices": unseen_detail["audio"] if unseen_detail else None,
    "AI splices": ia_detail["audio_eer"] if ia_detail else None,
}

# ── Build the table ──────────────────────────────────────────────────────────
columns = ["Set", "Auth./Spliced", "τ_audio", "FAR (%) [95% CI]", "FRR (%) [95% CI]",
           "Mean error (%) [95% CI]", "Self-cal. EER (%) [95% CI]"]
rows = []
for set_name, result in audio_level_sources.items():
    if result is None:
        rows.append({c: ("n/a" if c != "Set" else set_name) for c in columns})
        continue
    s = summarize_audio_level(result)
    rows.append({
        "Set": set_name,
        "Auth./Spliced": f"{s['n_auth']}/{s['n_spliced']}",
        "τ_audio": f"{s['tau']:.4f}",
        "FAR (%) [95% CI]": fmt(s["ci"]["far"]),
        "FRR (%) [95% CI]": fmt(s["ci"]["frr"]),
        "Mean error (%) [95% CI]": fmt(s["ci"]["mean_err"]),
        "Self-cal. EER (%) [95% CI]": fmt(s["ci"]["eer"]),
    })

table = pd.DataFrame(rows, columns=columns)

# ── Display and export ───────────────────────────────────────────────────────
print("\nTable. Audio-level detection performance at the frozen threshold "
      f"(Euclidean distance, {int(CONFIDENCE*100)}% stratified bootstrap CIs, "
      f"{N_RESAMPLES} resamples)\n")
print(table.to_string(index=False))

csv_path = os.path.join(output_path, f"audio_level_report_table_bootstrap_{eval_run_name}.csv")
table.to_csv(csv_path, index=False, encoding="utf-8")
print(f"\nCSV saved to {csv_path}")

tex_path = os.path.join(output_path, f"audio_level_report_table_bootstrap_{eval_run_name}.tex")
with open(tex_path, "w", encoding="utf-8") as f:
    f.write(table.to_latex(index=False, escape=True,
                           column_format="l" + "c" * (len(columns) - 1)))
print(f"LaTeX saved to {tex_path}")

# STANDALONE CELL: Table 3.4 — Window-level detection (Euclidean, frozen threshold)
# Reads only the pickles saved on Drive. No model, datasets or notebook state needed.
# Columns: genuine/impostor pairs, tau_window, FAR, FRR, full EER, balanced EER.

import os, pickle
import numpy as np
import pandas as pd
from sklearn.metrics import roc_curve
from google.colab import drive

drive.mount('/content/drive')

output_path = "/content/drive/MyDrive/AudioAuthentication_results_nfft2048_NV_3_FullSpectrum"
run_name = "euclidean_uv_epochs840_val15_win1_cosface_outdim64"
eval_run_name = f"{run_name}_40_nm_medf3_entw10"

N_REPEATS = 1000      # balanced-subsampling repetitions
SEED = 42
DECIMALS = 4


# Helpers
def load_pickle(file_name):
    """Loads a pickle from output_path; returns None (with a message) if missing."""
    path = os.path.join(output_path, file_name)
    if not os.path.exists(path):
        print(f"NOT FOUND: {path}")
        return None
    with open(path, "rb") as f:
        return pickle.load(f)


def eer_from_scores(scores, labels):
    """EER with the project's convention: label 1 = genuine, 0 = impostor,
    higher score = more 'spliced' (scores inverted, as in calculate_eer)."""
    fpr, tpr, _ = roc_curve(labels, -scores, pos_label=1)
    fnr = 1.0 - tpr
    idx = np.argmin(np.abs(fpr - fnr))
    return float((fpr[idx] + fnr[idx]) / 2.0)


def far_frr(scores, labels, threshold):
    """FAR: impostors NOT flagged. FRR: genuine wrongly flagged (flag = score > threshold)."""
    flagged = scores > threshold
    return float((~flagged[labels == 0]).mean()), float(flagged[labels == 1].mean())


def window_summary(window_result, n_repeats=N_REPEATS, seed=SEED):
    """Full-set FAR/FRR/EER at the frozen threshold, plus balanced EER
    (all impostors + an equal number of genuine pairs drawn without replacement)."""
    scores = np.asarray(window_result["scores"], dtype=np.float64)
    labels = np.asarray(window_result["labels"])
    threshold = float(window_result["optimal_threshold"])

    finite = np.isfinite(scores)                     # SNR-type scores can be inf
    if not finite.all():
        print(f"   dropping {(~finite).sum()} non-finite scores")
        scores, labels = scores[finite], labels[finite]

    genuine_idx = np.flatnonzero(labels == 1)
    impostor_idx = np.flatnonzero(labels == 0)
    far, frr = far_frr(scores, labels, threshold)

    rng = np.random.default_rng(seed)
    balanced_eers = np.empty(n_repeats)
    for i in range(n_repeats):
        idx = np.concatenate([rng.choice(genuine_idx, size=len(impostor_idx), replace=False),
                              impostor_idx])
        balanced_eers[i] = eer_from_scores(scores[idx], labels[idx])

    return {
        "n_genuine": len(genuine_idx), "n_impostor": len(impostor_idx), "tau": threshold,
        "far": far, "frr": frr, "eer_full": eer_from_scores(scores, labels),
        "eer_bal_mean": balanced_eers.mean(), "eer_bal_std": balanced_eers.std(),
    }


def pct(x, d=DECIMALS):
    return f"{100 * x:.{d}f}"


# Load each evaluation set (Euclidean, window level)
METRICS = ["euclidean", "mahalanobis", "manhattan", "snr"]
METRIC_LABELS = {"euclidean": "Euclidiana", "mahalanobis": "Mahalanobis",
                 "manhattan": "Manhattan", "snr": "SNR"}

def metric_tag(m):
    return "" if m == "euclidean" else f"{m}_"

def window_result_for(set_name, metric):
    """Window-level result dict for (set, metric), following the names used when saving."""
    if set_name == "Test":
        name = (f"eer_detail_{eval_run_name}.pkl" if metric == "euclidean"
                else f"eer_detail_final_test_{metric}_{eval_run_name}.pkl")
    elif set_name == "Unseen devices":
        name = f"eer_detail_unseen_devices_{metric_tag(metric)}{eval_run_name}.pkl"
    elif set_name == "AI splices":
        name = f"ia_splicing_detail_{metric_tag(metric)}{eval_run_name}.pkl"
    else:
        return None
    detail = load_pickle(name)
    return detail["window"] if detail else None

# Euclidean-only subsets (clean / noise) live in the experiment pickle
experiment = load_pickle(f"experiment_{eval_run_name}.pkl")
euclidean_only = {
    "Test, clean only": experiment["clean_results"]["window"] if experiment else None,
    "Test, noise only": experiment["noise_results"]["window"] if experiment else None,
}

# (set, metric, window_result), in the order you want them in the table
jobs = []
for set_name in ["Test", "Unseen devices", "AI splices"]:
    for metric in METRICS:
        jobs.append((set_name, metric, window_result_for(set_name, metric)))
for set_name, result in euclidean_only.items():
    jobs.append((set_name, "euclidean", result))

# Build the table
columns = ["Set", "Metric", "Genuine pairs", "Impostor pairs", "τ_window", "FAR (%)", "FRR (%)",
           "Full EER (%)", "Balanced EER (%) (mean ± s.d.)"]
rows, raw_records = [], []

for set_name, metric, window_result in jobs:
    if window_result is None or "scores" not in window_result:
        print(f"[{set_name} | {metric}] scores/labels unavailable — skipped.")
        continue
    print(f"[{set_name} | {metric}] computing...")
    s = window_summary(window_result)
    raw_records.append({"set": set_name, "metric": metric, **s})
    rows.append({
        "Set": set_name,
        "Metric": METRIC_LABELS[metric],
        "Genuine pairs": f"{s['n_genuine']:,}",
        "Impostor pairs": f"{s['n_impostor']:,}",
        "τ_window": f"{s['tau']:.4f}",
        "FAR (%)": pct(s["far"], 2),
        "FRR (%)": pct(s["frr"], 2),
        "Full EER (%)": pct(s["eer_full"], 2),
        "Balanced EER (%) (mean ± s.d.)": f"{pct(s['eer_bal_mean'], 2)} ± {pct(s['eer_bal_std'], 2)}",
    })

table = pd.DataFrame(rows, columns=columns)

# Display and export
print(f"\nWindow-level detection, frozen thresholds "
      f"(balanced EER: {N_REPEATS} subsamples, genuine pairs matched to impostor count)\n")
print(table.to_string(index=False))

csv_path = os.path.join(output_path, f"table_window_level_{eval_run_name}.csv")
table.to_csv(csv_path, index=False, encoding="utf-8")
pd.DataFrame(raw_records).to_csv(
    os.path.join(output_path, f"table_window_level_raw_{eval_run_name}.csv"), index=False)
print(f"\nCSV saved to {csv_path}")

# Check that supports the "balanced vs full differ by < 0.25 pp" claim in the Annex
raw = pd.DataFrame(raw_records)
raw["diff_pp"] = (raw["eer_bal_mean"] - raw["eer_full"]).abs() * 100
print(f"\nMax |balanced - full| EER difference: {raw['diff_pp'].max():.4f} pp "
      f"(row: {raw.loc[raw['diff_pp'].idxmax(), ['set', 'metric']].tolist()})")

# Standalone cell: generates Tables 3.1-3.5 (rendered tables + CSV) reading only what is saved in Drive.
import os, sys, pickle
import numpy as np
import pandas as pd
from google.colab import drive
from IPython.display import display

drive.mount('/content/drive')
sys.path.append('/content/drive/MyDrive/AudioAuthentication')
from eer_evaluation import calculate_eer, calculate_far_frr_at_threshold

output_path = "/content/drive/MyDrive/AudioAuthentication_results_nfft2048_NV_3_FullSpectrum"
run_name = "euclidean_uv_epochs840_val15_win1_cosface_outdim64"
eval_run_name = f"{run_name}_40_nm_medf3_entw10"
METRICS = ["euclidean", "manhattan", "mahalanobis", "snr"]
NAMES = {"euclidean": "Euclidean", "manhattan": "Manhattan", "mahalanobis": "Mahalanobis", "snr": "SNR"}


def show(df):
    """Display a DataFrame as a regular rendered table (no index)."""
    display(df.style.hide(axis="index"))


def tag(m):
    return "" if m == "euclidean" else f"{m}_"


def load(name):
    p = os.path.join(output_path, name)
    if not os.path.exists(p):
        print(f"NOT FOUND: {name}")
        return None
    with open(p, "rb") as f:
        return pickle.load(f)


SETS = {
    "Test": (lambda m: f"eer_detail_{eval_run_name}.pkl" if m == "euclidean"
             else f"eer_detail_final_test_{m}_{eval_run_name}.pkl", "audio"),
    "AI splicing": (lambda m: f"ia_splicing_detail_{tag(m)}{eval_run_name}.pkl", "audio_eer"),
    "Unseen devices": (lambda m: f"eer_detail_unseen_devices_{tag(m)}{eval_run_name}.pkl", "audio"),
}
experiment = load(f"experiment_{eval_run_name}.pkl")  # contains clean/noise/calibration (Euclidean only)


def clean(res):
    s, l = np.asarray(res["scores"], float), np.asarray(res["labels"])
    ok = np.isfinite(s)  # SNR can return inf
    return s[ok], l[ok], float(res["optimal_threshold"])


def row(set_name, metric, level, res):
    s, l, thr = clean(res)
    far_f, frr_f = calculate_far_frr_at_threshold(s, l, thr)
    eer_sc, thr_sc = calculate_eer(s, l)
    far_s, frr_s = calculate_far_frr_at_threshold(s, l, thr_sc)
    return {"Set": set_name, "Metric": NAMES[metric], "level": level,
            "n_gen": int((l == 1).sum()), "n_imp": int((l == 0).sum()),
            "τ frozen": thr, "FAR frozen (%)": 100 * far_f, "FRR frozen (%)": 100 * frr_f,
            "HTER frozen (%)": 50 * (far_f + frr_f),
            "τ self-cal.": thr_sc, "FAR self-cal. (%)": 100 * far_s, "FRR self-cal. (%)": 100 * frr_s,
            "EER self-cal. (%)": 100 * eer_sc}


rows = []
for set_name, (fname, audio_key) in SETS.items():
    for m in METRICS:
        d = load(fname(m))
        if d is None:
            continue
        rows.append(row(set_name, m, "audio", d[audio_key]))
        rows.append(row(set_name, m, "window", d["window"]))
if experiment:  # clean / noise (Euclidean, frozen threshold)
    for label, key in [("Test, clean only", "clean_results"), ("Test, noise only", "noise_results")]:
        if experiment.get(key):
            for level in ("audio", "window"):
                rows.append(row(label, "euclidean", level, experiment[key][level]))
det = pd.DataFrame(rows)
det.to_csv(os.path.join(output_path, f"detection_results_tables_{eval_run_name}.csv"), index=False)

#  frozen thresholds and calibration EER
t31 = []
for m in METRICS:
    d = load(SETS["Test"][0](m))
    thr_a = d["audio"]["optimal_threshold"] if d else np.nan
    thr_w = d["window"]["optimal_threshold"] if d else np.nan
    eer_a = eer_w = np.nan
    if m == "euclidean" and experiment:  # the other 3 calibrations were not saved in a pickle
        eer_a = 100 * experiment["calibration_results"]["audio"]["eer"]
        eer_w = 100 * experiment["calibration_results"]["window"]["eer"]
    t31.append({"Metric": NAMES[m], "τ audio": thr_a, "τ window": thr_w,
                "Audio val. EER (%)": eer_a, "Window val. EER (%)": eer_w})
t31 = pd.DataFrame(t31)
print("\nTable ")
show(t31.round(4))

cols = ["Set", "Metric", "n_gen", "n_imp", "FAR frozen (%)", "FRR frozen (%)", "HTER frozen (%)",
        "FAR self-cal. (%)", "FRR self-cal. (%)", "EER self-cal. (%)"]
for level, num in (("audio", "3.2"), ("window", "3.3")):
    print(f"\nTable {num} — {level} level")
    show(det[det.level == level][cols].round(2))

# Table localization error (mean ± s.d., s), Euclidean
loc_src = {"Test": load(f"eer_detail_{eval_run_name}.pkl"),
           "Unseen": load(f"eer_detail_unseen_devices_{eval_run_name}.pkl"),
           "AI": load(f"ia_splicing_detail_{eval_run_name}.pkl")}
STRAT = {"baseline": "Baseline", "median": "Median", "entropy": "Entropy", "median_entropy": "Median+entropy"}
t34 = []
for k, name in STRAT.items():
    r = {"Strategy": name}
    for src, d in loc_src.items():
        if d is None:
            continue
        a = d["audio"]
        for key, lab in (("localization_error_stats", "all"), ("localization_error_stats_detected", "detected")):
            st = (a.get(key) or {}).get(k)
            r[f"{src}: {lab}"] = f"{st['mean_error_s']:.3f} ± {st['std_error_s']:.3f} (n={st['n_samples']})" if st else "—"
    t34.append(r)
print("\n")
show(pd.DataFrame(t34))

# Table discriminability EER for independent pairs
pair_files = {"Seen devices": ("device_discriminability_eer", eval_run_name),
              "Unseen devices": ("device_discriminability_eer", f"unseen_devices_{eval_run_name}"),
              "Real vs. AI": ("ia_discriminability_eer", eval_run_name)}
t35 = []
for pop, (prefix, rn) in pair_files.items():
    r = {"Population": pop}
    for m in METRICS:
        d = load(f"{prefix}_{m}_{rn}.pkl")
        r[NAMES[m]] = f"{100 * d['eer']:.2f}" if d else "—"
    t35.append(r)
print("\nTable (EER, %)")
show(pd.DataFrame(t35))

#  k-NN accuracy with CI (saved in the bootstrap)
boot = load(f"bootstrap_ci_{eval_run_name}.pkl")
if boot and boot.get("knn_accuracy"):
    ci = boot["knn_accuracy"]
    print(f"\nk-NN test: {100*ci['estimate']:.2f} % [{100*ci['ci_lower']:.2f}, {100*ci['ci_upper']:.2f}]")

# Standalone cell: Annex H tables (bootstrap CIs). Reads only files saved on Drive.
import os, pickle
import numpy as np
import pandas as pd
from google.colab import drive
from IPython.display import display

drive.mount('/content/drive')

output_path = "/content/drive/MyDrive/AudioAuthentication_results_nfft2048_NV_3_FullSpectrum"
run_name = "euclidean_uv_epochs840_val15_win1_cosface_outdim64"
eval_run_name = f"{run_name}_40_nm_medf3_entw10"

def show(df):
    display(df.style.hide(axis="index"))

def save(df, name):
    path = os.path.join(output_path, f"annex_H_{name}_{eval_run_name}.csv")
    df.to_csv(path, index=False, encoding="utf-8")
    print(f"CSV saved: {path}")

def fmt(ci, pct=True, d=2):
    """'estimate [lo, hi]' from a bootstrap dict."""
    k, u = (100.0, "") if pct else (1.0, "")
    return f"{ci['estimate']*k:.{d}f} [{ci['ci_lower']*k:.{d}f}, {ci['ci_upper']*k:.{d}f}]"

with open(os.path.join(output_path, f"bootstrap_ci_{eval_run_name}.pkl"), "rb") as f:
    boot = pickle.load(f)

SET_NAMES = {"final_test": "Test", "unseen": "Unseen devices", "ia_splicing": "AI splices",
             "device": "Seen devices", "unseen_device": "Unseen devices", "ia": "Real vs. AI"}
METRIC_NAMES = {"euclidean": "Euclidean", "manhattan": "Manhattan",
                "mahalanobis": "Mahalanobis", "snr": "SNR"}

def split_source(source):
    """'final_test_euclidean' -> ('Test', 'Euclidean'); 'unseen_device_snr' -> ('Unseen devices', 'SNR')."""
    prefix, metric = source.rsplit("_", 1)
    return SET_NAMES.get(prefix, prefix), METRIC_NAMES.get(metric, metric)

# ── H.1  Audio-level EER / FAR / FRR (frozen threshold) + calibrated thresholds ──
rows = []
for source, cis in boot["detection"].items():
    set_name, metric = split_source(source)
    rows.append({"Set": set_name, "Metric": metric,
                 "n": cis["eer"]["n_samples"],
                 "EER (%) [95% CI]": fmt(cis["eer"]),
                 "FAR (%) [95% CI]": fmt(cis["far"]),
                 "FRR (%) [95% CI]": fmt(cis["frr"])})
h1 = pd.DataFrame(rows)
print("\nTable H.1a. Audio-level detection, frozen threshold (95% stratified bootstrap CI)")
show(h1); save(h1, "H1a_detection")

rows = [{"Metric": METRIC_NAMES[m], "Audio threshold (val.) [95% CI]": fmt(ci, pct=False, d=4),
         "CI width": f"{ci['ci_upper'] - ci['ci_lower']:.4f}",
         "Relative width (%)": f"{100*(ci['ci_upper'] - ci['ci_lower'])/ci['estimate']:.1f}"}
        for m, ci in boot["calibrated_threshold"].items()]
h1b = pd.DataFrame(rows)
print("\nTable H.1b. Stability of the calibrated audio-level threshold (validation set)")
show(h1b); save(h1b, "H1b_threshold_stability")

# ── H.2  k-NN accuracy and pairwise discriminability EER ──
knn = boot["knn_accuracy"]
print(f"\nk-NN test accuracy (cluster bootstrap by audio): {fmt(knn)} %  (n={knn['n_samples']} audios)")

rows = []
for source, ci in boot["pairwise_eer"].items():
    set_name, metric = split_source(source)
    rows.append({"Population": set_name, "Metric": metric, "EER (%) [95% CI]": fmt(ci)})
h2 = pd.DataFrame(rows)
print("\nTable H.2. Pairwise discriminability EER (95% bootstrap CI)")
show(h2); save(h2, "H2_pairwise_eer")

# ── H.3  Localization: paired bootstrap per strategy ──
STRAT = {"baseline": "Baseline", "median": "Median", "entropy": "Entropy", "median_entropy": "Median + entropy"}
rows = []
for source, strategies in boot["localization"].items():
    set_name, _ = split_source(source)
    for key, ci in strategies.items():
        rows.append({
            "Set": set_name, "Strategy": STRAT.get(key, key),
            "Mean error (s) [95% CI]": fmt(ci["mean_error_s"], pct=False, d=3),
            "Hit rate (%) [95% CI]": fmt(ci["hit_rate"]),
            "Δ error vs baseline (s) [95% CI]": fmt(ci["mean_error_diff_vs_baseline_s"], pct=False, d=3)
                if "mean_error_diff_vs_baseline_s" in ci else "—",
            "Δ hit rate vs baseline (pp) [95% CI]": fmt(ci["hit_rate_diff_vs_baseline"])
                if "hit_rate_diff_vs_baseline" in ci else "—",
        })
h3 = pd.DataFrame(rows)
print("\nTable H.3. Localization strategies, paired bootstrap (hit = detected AND error <= 1 s)")
show(h3); save(h3, "H3_localization")

# ── H.4  Audio-level score strategies (baseline / median / median+entropy) ──
csv_candidates = [f"audio_score_strategy_eer_summary_4metrics_{eval_run_name}.csv",
                  f"audio_score_strategy_eer_summary_{eval_run_name}.csv"]
csv_path = next((os.path.join(output_path, c) for c in csv_candidates
                 if os.path.exists(os.path.join(output_path, c))), None)
if csv_path is None:
    print("NOT FOUND: strategy summary CSV")
else:
    print(f"\nUsing: {os.path.basename(csv_path)}")
    s = pd.read_csv(csv_path)
    def cell(prefix):
        return s.apply(lambda r: f"{r[f'{prefix}_pct']:.2f} [{r[f'{prefix}_ci_lower_pct']:.2f}, "
                                 f"{r[f'{prefix}_ci_upper_pct']:.2f}]", axis=1)
    h4 = pd.DataFrame({
        "Metric": s["distance_metric"].map(METRIC_NAMES),
        "Pool": s["pool"].map({"final_test": "Test", "unseen_devices": "Unseen devices"}),
        "Strategy": s["strategy"],
        "Frozen threshold": s["frozen_threshold"].round(4),
        "EER (%) [95% CI]": cell("eer"),
        "FAR (%) [95% CI]": cell("far"),
        "FRR (%) [95% CI]": cell("frr"),
    }).sort_values(["Pool", "Metric"], kind="stable")
    print("\nTable H.4. Audio-level score strategies (threshold calibrated on validation)")
    show(h4); save(h4, "H4_score_strategies")

# Standalone cell: Annex F tables (audio-level EER, frozen vs self-calibrated threshold)
# for Test, Unseen devices and AI splices, 4 distance metrics.
# Reads only the pickles saved on Drive.

import os, sys, pickle, csv
import numpy as np
from google.colab import drive

drive.mount('/content/drive')
sys.path.append('/content/drive/MyDrive/AudioAuthentication')
from eer_evaluation import calculate_eer, calculate_far_frr_at_threshold

output_path = "/content/drive/MyDrive/AudioAuthentication_results_nfft2048_NV_3_FullSpectrum"
run_name = "euclidean_uv_epochs840_val15_win1_cosface_outdim64"
eval_run_name = f"{run_name}_40_nm_medf3_entw10"

METRICS = ["euclidean", "manhattan", "mahalanobis", "snr"]


def tag(metric):
    return "" if metric == "euclidean" else f"{metric}_"


SETS = {
    "Test": (lambda m: f"eer_detail_{eval_run_name}.pkl" if m == "euclidean"
             else f"eer_detail_final_test_{m}_{eval_run_name}.pkl", "audio", "F.1"),
    "Unseen devices": (lambda m: f"eer_detail_unseen_devices_{tag(m)}{eval_run_name}.pkl", "audio", "F.2"),
    "AI splices": (lambda m: f"ia_splicing_detail_{tag(m)}{eval_run_name}.pkl", "audio_eer", "F.3"),
}

records = []
for set_name, (name_fn, key, table_id) in SETS.items():
    print(f"\n=== Table {table_id}. Audio-level EER, {set_name} ===")
    print(f"{'Metric':<13}{'n_auth':>7}{'n_spl':>7}{'EER (%)':>9}{'Thr frozen':>12}{'Thr self':>10}"
          f"{'FAR(F)':>8}{'FRR(F)':>8}{'%auth>thr':>11}{'%spl>thr':>10}{'max auth':>10}{'max spl':>9}")
    for metric in METRICS:
        path = os.path.join(output_path, name_fn(metric))
        if not os.path.exists(path):
            print(f"NOT FOUND: {path}")
            continue
        with open(path, "rb") as f:
            res = pickle.load(f)[key]

        scores = np.asarray(res["scores"], dtype=np.float64)
        labels = np.asarray(res["labels"])            # 1 = authentic, 0 = spliced
        finite = np.isfinite(scores)                  # SNR can return inf
        scores, labels = scores[finite], labels[finite]

        frozen_thr = float(res["optimal_threshold"])
        eer, self_thr = calculate_eer(scores, labels)
        far_f, frr_f = calculate_far_frr_at_threshold(scores, labels, frozen_thr)

        auth, spl = scores[labels == 1], scores[labels == 0]
        frac_auth_above = float((auth > frozen_thr).mean())
        frac_spl_above = float((spl > frozen_thr).mean())

        records.append(dict(set=set_name, table=table_id, metric=metric,
                            n_authentic=len(auth), n_spliced=len(spl),
                            eer_pct=100 * eer, thr_frozen=frozen_thr, thr_self=self_thr,
                            far_frozen_pct=100 * far_f, frr_frozen_pct=100 * frr_f,
                            pct_auth_above_frozen=100 * frac_auth_above,
                            pct_spliced_above_frozen=100 * frac_spl_above,
                            max_auth=float(auth.max()), max_spliced=float(spl.max())))
        print(f"{metric:<13}{len(auth):>7}{len(spl):>7}{100*eer:>9.1f}{frozen_thr:>12.4f}{self_thr:>10.4f}"
              f"{100*far_f:>8.1f}{100*frr_f:>8.1f}{100*frac_auth_above:>11.1f}{100*frac_spl_above:>10.1f}"
              f"{auth.max():>10.4f}{spl.max():>9.4f}")

for set_name, (_, _, table_id) in SETS.items():
    print(f"\nTable {table_id} - {set_name}\n")
    print("| Métrica | EER (%) | Umbral congelado | Umbral autocalibrado |")
    print("|---|---|---|---|")
    for r in records:
        if r["set"] == set_name:
            print(f"| {r['metric']} | {r['eer_pct']:.1f} | {r['thr_frozen']:.4f} | {r['thr_self']:.4f} |")

csv_path = os.path.join(output_path, f"annex_F_audio_level_tables_{eval_run_name}.csv")
with open(csv_path, "w", newline="", encoding="utf-8") as f:
    writer = csv.DictWriter(f, fieldnames=list(records[0].keys()))
    writer.writeheader()
    writer.writerows(records)
print(f"\nCSV saved to {csv_path}")

