# Standalone cell: single-example forensic report on a NOISE -> NOISE splice
# (same protocol as the TEST block: generate_simple_splicing, top_db=TOP_DB, no edge margin).
# Needs only the files saved on Drive. Restart-safe.

import os, sys, pickle, random
import numpy as np
import torch, torch.nn as nn, torch.nn.functional as F
import matplotlib.pyplot as plt
import matplotlib.gridspec as gridspec
from datetime import datetime
from google.colab import drive

drive.mount('/content/drive')
sys.path.append('/content/drive/MyDrive/AudioAuthentication')
from eer_evaluation import (generate_simple_splicing, entropy_weighted_localization,
                            _apply_median_filter, _local_distance_entropy,
                            _audio_embeddings, _consecutive_distances)

# ── Configuration (must match the original run) ──
output_path = "/content/drive/MyDrive/AudioAuthentication_results_nfft2048_NV_3_FullSpectrum"
run_name = "euclidean_uv_epochs840_val15_win1_cosface_outdim64"
eval_run_name = f"{run_name}_40_nm_medf3_entw10"

SR, N_FFT, HOP_LENGTH_FFT = 44100, 2048, 2048
WIN_SEC, HOP_SEC = 1.0, 0.25
OUT_DIM, TOP_DB = 64, 30
MEDIAN_KERNEL, ENTROPY_WINDOW = 3, 10
DPI = 400

CONDITION_A = "speech_noise"   # condition of the source audio (before the cut)
CONDITION_B = "speech_noise"   # condition of the destination audio (after the cut)
SEED = 42                      # change it to draw a different device pair / take

random.seed(SEED); np.random.seed(SEED); torch.manual_seed(SEED)
device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')

# ── Architecture (identical to the training notebook) ──
class Backbone(nn.Sequential):
    def __init__(self, p=0.1):
        super().__init__(
            nn.Conv2d(1, 64, 3, padding=1), nn.BatchNorm2d(64), nn.ReLU(),
            nn.MaxPool2d(2, ceil_mode=True), nn.Dropout2d(p),
            nn.Conv2d(64, 128, 3, padding=1), nn.BatchNorm2d(128), nn.ReLU(),
            nn.MaxPool2d(2, ceil_mode=True), nn.Dropout2d(p),
            nn.Conv2d(128, 256, 3, padding=1), nn.BatchNorm2d(256), nn.ReLU(),
            nn.Dropout2d(p),
        )

class Neck(nn.Sequential):
    def __init__(self, out_dim, p=0.1):
        super().__init__(
            nn.AdaptiveAvgPool2d(1), nn.Flatten(),
            nn.Linear(256, 1024), nn.ReLU(), nn.Dropout(p),
            nn.Linear(1024, 256), nn.ReLU(), nn.Dropout(p),
            nn.Linear(256, out_dim),
        )

class EmbeddingNet(nn.Module):
    def __init__(self, out_dim):
        super().__init__()
        self.backbone, self.neck = Backbone(), Neck(out_dim)
    def forward(self, x, valid_input_time_lengths=None):
        return F.normalize(self.neck(self.backbone(x)), p=2, dim=1)

checkpoint = torch.load(os.path.join(output_path, f"siamese_model_{run_name}.pth"), map_location="cpu")
model = EmbeddingNet(OUT_DIM)
model.load_state_dict(checkpoint['model_state_dict'])
model.to(device).eval()

# ── Frozen audio-level threshold (Euclidean, calibrated on val_audios) ──
experiment_path = os.path.join(output_path, f"experiment_{eval_run_name}.pkl")
if os.path.exists(experiment_path):
    with open(experiment_path, "rb") as f:
        threshold = float(pickle.load(f)["calibrated_threshold"]["audio"])
else:  # fallback: the final-test detail stores the fixed threshold it used
    with open(os.path.join(output_path, f"eer_detail_{eval_run_name}.pkl"), "rb") as f:
        threshold = float(pickle.load(f)["audio"]["optimal_threshold"])
print(f"Frozen audio threshold (Euclidean): {threshold:.4f}")

# ── Test audios (never seen) ──
with open(os.path.join(output_path, "raw_split.pkl"), "rb") as f:
    test_audios = pickle.load(f)["test_audios"]

# ── Draw a cross-device pair with the requested conditions and splice it ──
dev_names = sorted({a['device'] for a in test_audios})
spliced_audio, cut_sample = None, None
for _ in range(1000):
    device_a, device_b = random.sample(dev_names, 2)
    pool_a = [a for a in test_audios if a['device'] == device_a and a['condition'] == CONDITION_A]
    pool_b = [a for a in test_audios if a['device'] == device_b and a['condition'] == CONDITION_B]
    if not pool_a or not pool_b:
        continue
    audio_a, audio_b = random.choice(pool_a), random.choice(pool_b)
    spliced_audio, cut_sample = generate_simple_splicing(audio_a['audio'], audio_b['audio'], top_db=TOP_DB)
    if spliced_audio is not None:
        break
if spliced_audio is None:
    raise RuntimeError("No valid splice found; try another SEED.")

real_cut_time = cut_sample / SR
print(f"Splice: {device_a} ({audio_a['condition']}, {audio_a['filename']}) -> "
      f"{device_b} ({audio_b['condition']}, {audio_b['filename']})")
print(f"Real cut point: sample {cut_sample} - {real_cut_time:.4f} s")

# ── Embeddings and consecutive distances (same functions as the evaluation) ──
embeddings, timestamps = _audio_embeddings(
    spliced_audio, model, device=device, sr=SR, win_sec=WIN_SEC, hop_sec=HOP_SEC,
    n_fft=N_FFT, hop_length_fft=HOP_LENGTH_FFT)
distances = _consecutive_distances(embeddings, distance_metric="euclidean")
dist_times = np.asarray(timestamps[1:])

max_idx = int(np.argmax(distances))
splice_time = float(dist_times[max_idx])
has_splice = bool(distances[max_idx] > threshold)

entropy_candidate = entropy_weighted_localization(distances, list(dist_times), entropy_window=ENTROPY_WINDOW)
has_splice_entropy = entropy_candidate['entropy_max_distance'] > threshold

print(f"\nMax distance found: {distances[max_idx]:.4f}")
print(f"Current threshold:  {threshold:.4f}")
print(f"Detected splice?:   {has_splice}")
if has_splice:
    print(f"Model detected: splice at {splice_time:.4f}s | error: {abs(real_cut_time - splice_time):.4f}s")
else:
    print("Model detected: AUTHENTIC AUDIO (did not exceed the threshold)")
if has_splice_entropy:
    t_ent = entropy_candidate['entropy_detected_time_s']
    print(f"Entropy-weighted candidate: {t_ent:.4f}s | error: {abs(real_cut_time - t_ent):.4f}s")
else:
    print("Entropy-weighted candidate: no distance above threshold")

# ── Figure 1: forensic report (waveform, distances, similarity map) ──
n_win = len(embeddings)
similarity = np.linalg.norm(embeddings[:, None, :] - embeddings[None, :, :], axis=-1)

fig = plt.figure(figsize=(18, 14))
fig.suptitle(f"AUDIO AUTHENTICITY FORENSIC REPORT — {CONDITION_A} - {CONDITION_B}\n"
             f"{device_a} - {device_b} | {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}",
             fontsize=14, fontweight='bold')
gs = gridspec.GridSpec(2, 2, figure=fig, hspace=0.4, wspace=0.35)

ax1 = fig.add_subplot(gs[0, :])
ax1.plot(np.arange(len(spliced_audio)) / SR, spliced_audio, color='steelblue', linewidth=0.5, alpha=0.8)
ax1.axvline(real_cut_time, color='green', linewidth=2, linestyle=':', label=f'Ground truth: {real_cut_time:.4f}s')
if has_splice:
    ax1.axvline(splice_time, color='red', linewidth=2, linestyle='--', label=f'Splice detected: {splice_time:.4f}s')
if has_splice_entropy:
    ax1.axvline(entropy_candidate['entropy_detected_time_s'], color='magenta', linewidth=2, linestyle=':',
                label=f"Entropy-weighted candidate: {entropy_candidate['entropy_detected_time_s']:.4f}s")
ax1.set_title('Waveform — Analyzed Audio Signal', fontweight='bold')
ax1.set_xlabel('Time (seconds)'); ax1.set_ylabel('Amplitude')
ax1.legend(fontsize=11); ax1.grid(True, alpha=0.3)

ax2 = fig.add_subplot(gs[1, 0])
ax2.plot(dist_times, distances, color='darkorange', linewidth=1.5, marker='o', markersize=3,
         label='Distance between segments')
ax2.axhline(threshold, color='gray', linestyle=':', linewidth=1.5, label=f'Threshold = {threshold:.4f}')
ax2.axvline(real_cut_time, color='green', linestyle=':', linewidth=2, label='Ground truth')
ax2.scatter([splice_time], [distances[max_idx]], color='red', s=100, zorder=5, label=f'Max peak: {splice_time:.4f}s')
ax2.set_title('Euclidean Distance Between Consecutive Segments', fontweight='bold')
ax2.set_xlabel('Time (seconds)'); ax2.set_ylabel('Distance in embedding space')
ax2.legend(fontsize=9); ax2.grid(True, alpha=0.3)

ax3 = fig.add_subplot(gs[1, 1])
im = ax3.imshow(similarity, cmap='hot_r', aspect='auto',
                extent=[timestamps[0], timestamps[-1], timestamps[-1], timestamps[0]])
plt.colorbar(im, ax=ax3, label='Euclidean distance')
ax3.axvline(real_cut_time, color='cyan', linewidth=1.5, linestyle='--', label=f'Ground truth: {real_cut_time:.4f}s')
ax3.axhline(real_cut_time, color='cyan', linewidth=1.5, linestyle='--')
ax3.set_title('Similarity Map Between Segments\n(darker = more similar)', fontweight='bold')
ax3.set_xlabel('Time (seconds)'); ax3.set_ylabel('Time (seconds)'); ax3.legend(fontsize=9)

verdict = (f" SPLICE DETECTED at t = {splice_time:.4f}s (distance = {distances[max_idx]:.4f}, threshold = {threshold:.4f})"
           if has_splice else
           f" AUTHENTIC AUDIO — max distance {distances[max_idx]:.4f} < threshold {threshold:.4f}")
fig.text(0.5, 0.01, verdict, ha='center', fontsize=13, fontweight='bold',
         color='red' if has_splice else 'green',
         bbox=dict(boxstyle='round,pad=0.4', facecolor='lightyellow',
                   edgecolor='red' if has_splice else 'green'))
tag = f"{CONDITION_A}_to_{CONDITION_B}_seed{SEED}"
report_path = os.path.join(output_path, f"forensic_report_{tag}_{eval_run_name}.png")
plt.savefig(report_path, dpi=DPI, bbox_inches='tight'); plt.show()
print(f"Saved: {report_path}")

# ── Figure 2: localization strategy comparison (raw / median / entropy / median+entropy) ──
filtered = _apply_median_filter(distances, MEDIAN_KERNEL)
score_entropy_raw = distances / (_local_distance_entropy(distances, ENTROPY_WINDOW) + 1e-10)
score_combined = filtered / (_local_distance_entropy(filtered, ENTROPY_WINDOW) + 1e-10)

panels = [
    ("Raw Distance (Baseline)", distances, True, 'darkorange'),
    (f"Median-Filtered Distance (k={MEDIAN_KERNEL})", filtered, True, 'steelblue'),
    (f"Entropy-Weighted Score (window={ENTROPY_WINDOW})", score_entropy_raw, False, 'seagreen'),
    ("Median-Filtered + Entropy-Weighted Score", score_combined, False, 'purple'),
]
fig, axes = plt.subplots(2, 2, figsize=(14, 10))
print("\n=== Strategy comparison summary ===")
for ax, (title, curve, is_distance, color) in zip(axes.ravel(), panels):
    peak = int(np.argmax(curve)); t_peak = float(dist_times[peak]); err = abs(t_peak - real_cut_time)
    ax.plot(dist_times, curve, color=color, linewidth=1.2, marker='o', markersize=3, label='Signal')
    ax.axvline(real_cut_time, color='green', linestyle=':', linewidth=2, label=f'Ground truth: {real_cut_time:.4f}s')
    ax.scatter([t_peak], [curve[peak]], color='red', s=90, zorder=5, label=f'Detected peak: {t_peak:.4f}s')
    if is_distance:
        ax.axhline(threshold, color='gray', linestyle='--', linewidth=1.2, label=f'Threshold = {threshold:.4f}')
    ax.set_title(f"{title}\nLocalization error: {err:.4f}s", fontweight='bold', fontsize=10)
    ax.set_xlabel('Time (seconds)'); ax.set_ylabel('Distance' if is_distance else 'Entropy-weighted score')
    ax.legend(fontsize=8); ax.grid(True, alpha=0.3)
    print(f"{title:<45} error = {err:.4f}s (detected at {t_peak:.4f}s)")
fig.suptitle(f'Splice-Peak Localization — Strategy Comparison ({CONDITION_A} → {CONDITION_B})',
             fontsize=14, fontweight='bold')
plt.tight_layout(rect=[0, 0, 1, 0.96])
comparison_path = os.path.join(output_path, f"filtering_comparison_{tag}_{eval_run_name}.png")
plt.savefig(comparison_path, dpi=DPI, bbox_inches='tight'); plt.show()
print(f"Saved: {comparison_path}")

