print("\n=== Captions ready to paste ===")
for number, label, pdf_name, caption in FIGURES:
    print(f"Figura I.{number}. {caption}")

if missing:
    print("\n=== NOT FOUND (check file names in Drive) ===")
    for number, pdf_name in missing:
        print(f"I.{number}: {pdf_name}")
